INSERT INTO requirements
    (category_sub_id, identifier,title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='FCO'), 'FSU-FCO-01', 'Requirements Coverage', 'All explicitly documented functional requirements (from SRS, user stories, use cases, epics, or product backlog) have at least one corresponding implemented and testable function in the delivered product.', 'HIGH', 'APPROVED', 'Traceability matrix shows 100% forward traceability from requirements to implemented features/tests; gap analysis identifies zero uncovered requirements.', 'ISO 25010', 'Product not implemented as designed'),
    ((select id from category_sub where short_name='FCO'), 'FSU-FCO-02', 'Task/Objective Coverage', 'For each user task or business objective defined in the requirements or user journey maps, the system provides the complete set of functions needed to achieve the objective end-to-end without requiring external workarounds or third-party tools (unless explicitly allowed).', 'HIGH', 'APPROVED', 'Example: In an e-commerce system, the "purchase product" objective includes search → view details → add to cart → checkout → payment → order confirmation; all steps are present.', 'ISO 25010', 'End-to-end objective not met'),
    ((select id from category_sub where short_name='FCO'), 'FSU-FCO-03', 'Implicit Need Coverage', 'Functions necessary to meet implied needs (commonly expected in the domain, legal/regulatory obligations, standards compliance, or typical user expectations in the context of use) are implemented.', 'HIGH', 'APPROVED', 'Login/logout for any authenticated system; password reset; basic error handling and user feedback; GDPR/CCPA consent mechanisms if personal data is processed; accessibility basics if public-facing.', 'ISO 25010', 'Standards / typical expectations not met'),
    ((select id from category_sub where short_name='FCO'), 'FSU-FCO-04', 'Boundary and Edge Case Coverage', 'The system handles all specified boundary conditions, variants, and exceptions for each task without missing handling logic that would prevent task completion.', 'HIGH', 'APPROVED', 'Example: For a file upload feature, supports all documented file types, sizes, and quantities; missing support for one required format = incompleteness.', 'ISO 25010', 'Incomplete boundary and edge case testing coverage.'),
    ((select id from category_sub where short_name='FCO'), 'FSU-FCO-05', 'User Role / Persona Coverage', 'All intended user roles/personas (admin, editor, viewer, guest, etc.) have the complete set of functions required for their objectives as defined in the requirements.', 'HIGH', 'APPROVED', 'Role-based use-case coverage; no role is blocked from completing its objectives due to missing capabilities.', 'ISO 25010', 'Roles / personas missing or incomplete to meet user expectations'),
    ((select id from category_sub where short_name='FCO'), 'FSU-FCO-06', 'Workflow / Process Completeness', 'End-to-end workflows (multi-step processes) include all necessary steps, transitions, and decision points without gaps that force users to exit the system or use manual processes.', 'HIGH', 'APPROVED', 'Example: In a loan application system, the full flow from application submission → document upload → review → approval/rejection → notification is fully covered.', 'ISO 25010', 'Defined workflows are inaccurate or incomplete.'),
    ((select id from category_sub where short_name='FCO'), 'FSU-FCO-07', 'Data Lifecycle Coverage', 'For each entity/type of data managed by the system, the complete CRUD (Create, Read, Update, Delete) lifecycle — plus any required archiving, export, import, or reporting functions — is implemented where specified.', 'HIGH', 'APPROVED', 'Export/reporting functions missing even though required for compliance or business objectives.', 'ISO 25010', 'Export/reporting functions missing.'),
    ((select id from category_sub where short_name='FCO'), 'FSU-FCO-08', 'Interface / Integration Completeness', 'All specified external interfaces, APIs, integrations, or data exchanges provide the full set of required operations (e.g., all endpoints documented in an OpenAPI spec are implemented and operational).', 'HIGH', 'APPROVED', 'Verify all elements of user stories / integration documentation for completeness and accuracy.', 'ISO 25010', 'Incomplete / incorrect user interface and/or integration with partner systems.'),
    ((select id from category_sub where short_name='FCO'), 'FSU-FCO-09', 'Localization / Internationalization Completeness', 'If multi-language or multi-region support is specified, all functions and user objectives are fully available in each supported language/locale without missing translations or culture-specific adaptations.', 'HIGH', 'APPROVED', 'Verify local and international specific currencies, formatting, and languages are supported.', 'WCAG 2.2 - 1.3.4', 'Reputational risk.'),
    ((select id from category_sub where short_name='FCO'), 'FSU-FCO-10','No Missing Core Domain Functions', 'Domain-specific mandatory functions (identified via domain analysis, competitor benchmarking, or regulatory requirements) are present.', 'HIGH', 'APPROVED', 'Example: In a banking app: transfer funds, view balance, transaction history, bill pay, etc., are all implemented; omission of one = incompleteness.', 'WCAG 2.2 - 1.3.4', 'Incomplete product / feature set.');
INSERT INTO requirements
    (category_sub_id, identifier,title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='FCR'), 'FSU-FCR-01', 'Requirements-to-Function Traceability Coverage', '100% of all explicitly documented functional requirements (SRS, user stories, use cases, epics, or product specifications) trace forward to at least one implemented and verifiable function in the delivered product, with no uncovered items identified in the traceability matrix.', 'HIGH', 'APPROVED', 'Ensures the delivered set of functions fully covers every stated requirement, directly addressing the definition of completeness as covering all specified tasks.', 'ISO/IEC 25010', 'Critical features are missing, leading to incomplete product delivery, user dissatisfaction, and potential contract/rework costs.'),
    ((select id from category_sub where short_name='FCR'), 'FSU-FCR-02', 'End-to-End User Task Coverage', 'For every major user task or business objective defined in requirements or user journey maps, the system provides all necessary functions to complete the task from initiation to successful outcome without requiring external tools, manual steps, or workarounds.', 'HIGH', 'APPROVED', 'Verifies that no intermediate steps or supporting functions are omitted, ensuring holistic coverage of user objectives.', 'ISO/IEC 25010', 'Users cannot achieve key goals independently, resulting in low adoption, support overload, and business process failures.'),
    ((select id from category_sub where short_name='FCR'), 'FSU-FCR-03', 'Implied Needs and Domain Expectation Coverage', 'All commonly expected or implied functions in the domain (e.g., login/logout, basic error feedback, password recovery, data export, compliance mechanisms) are implemented when not explicitly excluded.', 'HIGH', 'APPROVED', 'Completeness includes addressing implied needs that users reasonably expect, preventing obvious functional gaps.', 'ISO/IEC 25010', 'Product perceived as incomplete or unprofessional, leading to negative reviews, lost trust, and competitive disadvantage.'),
    ((select id from category_sub where short_name='FCR'), 'FSU-FCR-04', 'User Role and Persona Completeness', 'Every defined user role or persona (e.g., admin, editor, viewer, guest) has the full set of functions required to fulfill their specified objectives, with no role-level gaps.', 'HIGH', 'APPROVED', 'Ensures completeness across diverse intended users, avoiding scenarios where certain users cannot perform necessary tasks.', 'ISO/IEC 25010', 'Certain user groups are excluded or severely limited, causing inequality in usage, compliance issues, or stakeholder rejection.'),
    ((select id from category_sub where short_name='FCR'), 'FSU-FCR-05', 'Data Entity Lifecycle Completeness', 'For each core data entity managed by the system, the complete lifecycle (create, read, update, delete, plus any required import/export, archive, or report functions) is fully supported as specified.', 'HIGH', 'APPROVED', 'Many tasks depend on full data handling; missing lifecycle stages create functional holes.', 'ISO/IEC 25010', 'Data becomes trapped or unmanageable, leading to operational blockages, data loss risks, and regulatory non-compliance.'),
    ((select id from category_sub where short_name='FCR'), 'FSU-FCR-06', 'Workflow and Process Step Completeness', 'Multi-step workflows include every required step, transition, decision point, and notification without gaps that interrupt or prevent completion.', 'HIGH', 'APPROVED', 'Ensures no breaks in process coverage, a frequent source of incompleteness in complex systems.', 'ISO/IEC 25010', 'Incomplete processes force manual intervention or failure, increasing errors, delays, and operational costs.'),
    ((select id from category_sub where short_name='FCR'), 'FSU-FCR-07', 'Boundary and Variant Coverage for Tasks', 'All specified boundary conditions, input variants, and exception paths for each task have corresponding handling functions, with no missing variants leading to incomplete task support.', 'HIGH', 'APPROVED', 'Completeness requires supporting the full range of specified scenarios, not just happy paths.', 'ISO/IEC 25010', 'Edge cases fail completely, causing partial system breakdowns, data corruption, or safety/security issues.'),
    ((select id from category_sub where short_name='FCR'), 'FSU-FCR-08', 'Interface and Integration Operation Completeness', 'All specified external interfaces, APIs, or integrations implement the complete set of required operations/endpoints as documented (e.g., full OpenAPI coverage).', 'HIGH', 'APPROVED', 'Missing API operations break task completion when external systems are involved.', 'ISO/IEC 25010', 'Integrations fail partially or fully, blocking dependent business processes and ecosystem functionality.'),
    ((select id from category_sub where short_name='FCR'), 'FSU-FCR-09', 'Localization and Multi-Context Completeness', 'When multi-language, multi-region, or multi-device support is specified, all functions and tasks are fully available and operational in each supported context without missing adaptations.', 'HIGH', 'APPROVED', 'Ensures completeness across intended usage contexts and user diversity.', 'ISO/IEC 25010', 'Users in certain locales/devices cannot complete tasks, limiting market reach and inclusivity.'),
    ((select id from category_sub where short_name='FCR'), 'FSU-FCR-10', 'Regulatory and Compliance Function Coverage', 'All functions mandated by regulations, standards, or legal requirements (e.g., audit logs, consent flows, data retention/deletion) are fully implemented as specified.', 'HIGH', 'APPROVED', 'Compliance functions are often "specified tasks"; omission creates legal incompleteness.', 'ISO/IEC 25010', 'Legal violations, fines, lawsuits, product withdrawal, or inability to operate in regulated markets.');
INSERT INTO quality_attribute_test_criteria
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='FAP'), 'FSU-FAP-01', 'Task Efficiency and Minimal Steps Coverage', 'For each specified task or objective, the implemented functions provide the minimal necessary steps to complete it successfully, with no extraneous or redundant interactions required.', 'HIGH', 'APPROVED', 'Ensures functions are streamlined and facilitate quick, effective accomplishment without unnecessary overhead, directly supporting task facilitation.', 'ISO/IEC 25010:2023 - Functional Appropriateness', 'Users experience bloated workflows, reduced productivity, increased frustration, and potential abandonment of the system.'),
    ((select id from category_sub where short_name='FAP'), 'FSU-FAP-02', 'Absence of Irrelevant Functions in Task Flows', 'No irrelevant, unused, or out-of-context functions or behaviors are presented or triggered during execution of a specified task (e.g., no unrelated prompts, mandatory detours, or distracting elements).', 'HIGH', 'APPROVED', 'Prevents dilution of focus and ensures functions remain appropriate by excluding unnecessary elements that hinder task accomplishment.', 'ISO/IEC 25010:2023 - Functional Appropriateness', 'Cognitive overload, user confusion, error-prone interactions, and degraded task performance occur.'),
    ((select id from category_sub where short_name='FAP'), 'FSU-FAP-03', 'Appropriate Granularity of Functions', 'Functions are provided at an appropriate level of granularity: neither too coarse (forcing complex manual workarounds) nor too fine (over-fragmenting simple tasks).', 'HIGH', 'APPROVED', 'Balances function design to optimally support task completion without imposing excessive or insufficient decomposition.', 'ISO/IEC 25010:2023 - Functional Appropriateness (facilitate accomplishment)', 'Users face inefficient manual assembly of steps or overwhelming micro-interactions, lowering efficiency and satisfaction.'),
    ((select id from category_sub where short_name='FAP'), 'FSU-FAP-04', 'Task-Focused Function Sequencing', 'The sequence and presentation of functions in a task flow logically align with natural user progression and best practices for the objective (e.g., logical order, progressive disclosure).', 'HIGH', 'APPROVED', 'Ensures functions guide users effectively through tasks in a facilitative manner.', 'ISO/IEC 25010:2023 - Functional Appropriateness', 'Illogical or counter-intuitive flows cause confusion, errors, rework, and increased task completion time.'),
    ((select id from category_sub where short_name='FAP'), 'FSU-FAP-05', 'No Unnecessary Data Entry or Repetition', 'Functions avoid requiring redundant data entry or repeated actions for the same task objective (e.g., auto-population, smart defaults, or session persistence where appropriate).', 'HIGH', 'APPROVED', 'Reduces friction and facilitates smoother accomplishment by minimizing avoidable effort.', 'ISO/IEC 25010:2023 - Functional Appropriateness', 'User fatigue, higher abandonment rates, and perceived poor design quality emerge.'),
    ((select id from category_sub where short_name='FAP'), 'FSU-FAP-06', 'Sufficient but Not Excessive Feedback', 'Functions provide appropriate feedback at key points in task execution (confirmation, progress, results) without overwhelming the user with irrelevant notifications.', 'HIGH', 'APPROVED', 'Feedback supports task awareness and completion without introducing distracting or unnecessary elements.', 'ISO/IEC 25010:2023 - Functional Appropriateness', 'Users lack confidence in progress or receive notification overload, leading to hesitation, errors, or disengagement.'),
    ((select id from category_sub where short_name='FAP'), 'FSU-FAP-07', 'Contextual Appropriateness of Functions', 'Functions adapt or behave appropriately based on task context, user state, or preconditions (e.g., disabling irrelevant options, showing task-specific tools).', 'HIGH', 'APPROVED', 'Ensures functions remain relevant and facilitative in varying contexts of use.', 'ISO/IEC 25010:2023 - Functional Appropriateness', 'Inappropriate function availability causes confusion, invalid actions, or missed opportunities for efficiency.'),
    ((select id from category_sub where short_name='FAP'), 'FSU-FAP-08', 'Error Prevention and Recovery Facilitation', 'Functions include built-in mechanisms to prevent task-disrupting errors and facilitate quick recovery without excessive steps or external help.', 'HIGH', 'APPROVED', 'Supports uninterrupted task accomplishment by making error handling appropriate and integrated.', 'ISO/IEC 25010:2023 - Functional Appropriateness', 'Frequent unrecoverable errors or cumbersome recovery processes increase failure rates and user dissatisfaction.'),
    ((select id from category_sub where short_name='FAP'), 'FSU-FAP-09', 'Task Objective Achievement Effectiveness', 'End-to-end testing shows that users (or simulated personas) can achieve 100% of specified objectives using the provided functions with minimal deviations or workarounds.', 'HIGH', 'APPROVED', 'Directly measures whether functions effectively enable objective completion in practice.', 'ISO/IEC 25010:2023 - Functional Appropriateness (facilitate accomplishment of objectives)', 'Objectives remain difficult or impossible to achieve optimally, resulting in business goal failure or poor perceived value.'),
    ((select id from category_sub where short_name='FAP'), 'FSU-FAP-10', 'No Over-Engineering or Feature Bloat in Core Tasks', 'Core task functions exclude unnecessary advanced features or options that are irrelevant to primary objectives (unless optional and hidden by default).', 'HIGH', 'APPROVED', 'Prevents bloat that complicates rather than facilitates primary task accomplishment.', 'ISO/IEC 25010:2023 - Functional Appropriateness', 'Core tasks become unnecessarily complex, slowing adoption, increasing training needs, and diluting focus on essential objectives.');
INSERT INTO quality_attribute_test_criteria
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((SELECT id FROM category_sub WHERE short_name = 'TIM'), 'PEF-TIM-01', 'Response Time for Critical User Interactions', 'Under normal load conditions (as defined in performance requirements), the system achieves average response times ≤ specified thresholds (e.g., < 2 seconds for page loads, < 500 ms for API calls, < 100 ms for UI feedback) for all critical user-facing interactions.', 'HIGH', 'APPROVED', 'Ensures interactive functions respond quickly enough to meet user expectations and productivity needs, directly aligning with time behaviour requirements.', 'ISO/IEC 25010:2023 - Time Behaviour', 'Users perceive the system as sluggish or unresponsive, leading to frustration, reduced productivity, increased abandonment rates, and poor user satisfaction.'),
    ((SELECT id FROM category_sub WHERE short_name = 'TIM'), 'PEF-TIM-02', 'Throughput Rate Under Expected Load', 'The system sustains the required transaction throughput rate (e.g., X transactions per second) without degradation when operating at the specified nominal or peak concurrent user load.', 'HIGH', 'APPROVED', 'Verifies that processing capacity meets throughput requirements for batch or concurrent operations.', 'ISO/IEC 25010:2023 - Time Behaviour', 'The system fails to handle expected volumes, causing queues, delays, or service unavailability during normal business peaks.'),
    ((SELECT id FROM category_sub WHERE short_name = 'TIM'), 'PEF-TIM-03', 'Peak Load Response Time Stability', 'Response times remain within acceptable limits (e.g., no more than 20% degradation from baseline) during stress testing at defined peak load levels for a sustained period.', 'HIGH', 'APPROVED', 'Tests stability of time behaviour under high demand, preventing unacceptable slowdowns.', 'ISO/IEC 25010:2023 - Time Behaviour', 'Sudden spikes cause unacceptable delays or timeouts, resulting in lost transactions, revenue impact, or SLA breaches.'),
    ((SELECT id FROM category_sub WHERE short_name = 'TIM'), 'PEF-TIM-04', 'Batch Processing Duration Compliance', 'Long-running batch jobs or background processes complete within the specified maximum elapsed time (e.g., nightly reports < 4 hours) under standard conditions.', 'HIGH', 'APPROVED', 'Ensures non-interactive tasks meet timing constraints critical for operational schedules.', 'ISO/IEC 25010:2023 - Time Behaviour', 'Delayed batch jobs disrupt downstream processes, reporting, or decision-making, causing operational inefficiencies or compliance failures.'),
    ((SELECT id FROM category_sub WHERE short_name = 'TIM'), 'PEF-TIM-05', 'Cold Start / Initialization Time', 'Application or service startup/initialization time (e.g., cold boot, first request after idle) does not exceed the defined maximum threshold (e.g., < 10 seconds for serverless functions).', 'HIGH', 'APPROVED', 'Addresses time behaviour for initial access or recovery scenarios, important for user-perceived performance.', 'ISO/IEC 25010:2023 - Time Behaviour', 'Excessive startup delays frustrate users, especially in mobile or on-demand services, leading to perceived unreliability.'),
    ((SELECT id FROM category_sub WHERE short_name = 'TIM'), 'PEF-TIM-06', 'Scalability of Response Time with Load', 'As load increases linearly (e.g., from 100 to 1000 concurrent users), response times scale predictably and stay within defined acceptable bounds (e.g., logarithmic or linear growth only).', 'HIGH', 'APPROVED', 'Confirms time behaviour maintains acceptable levels as demand grows, a key aspect of performance requirements.', 'ISO/IEC 25010:2023 - Time Behaviour', 'Non-linear degradation under growth leads to cascading failures, capacity planning errors, and costly emergency scaling.'),
    ((SELECT id FROM category_sub WHERE short_name = 'TIM'), 'PEF-TIM-07', 'Time Behaviour Consistency Across Scenarios', 'Response times for equivalent operations remain consistent (low variance, e.g., 95th percentile < 3× average) across different usage patterns, devices, or network conditions as specified.', 'HIGH', 'APPROVED', 'Ensures predictable and reliable time performance in varied real-world contexts.', 'ISO/IEC 25010:2023 - Time Behaviour', 'Inconsistent performance causes user distrust, poor experience on certain devices/networks, and increased support tickets.'),
    ((SELECT id FROM category_sub WHERE short_name = 'TIM'), 'PEF-TIM-08', 'Timeout and Error Handling Latency', 'When timeouts or errors occur due to overload or external dependencies, the system returns user feedback or graceful degradation within a short, specified time (e.g., < 5 seconds).', 'HIGH', 'APPROVED', 'Prevents indefinite hangs and ensures time behaviour includes appropriate failure handling.', 'ISO/IEC 25010:2023 - Time Behaviour', 'Prolonged hangs or silent failures during issues lead to user abandonment and negative perception of system reliability.'),
    ((SELECT id FROM category_sub WHERE short_name = 'TIM'), 'PEF-TIM-09', 'Real-Time or Near-Real-Time Processing Latency', 'For time-sensitive functions (e.g., streaming, monitoring, trading), end-to-end latency stays below strict thresholds (e.g., < 100 ms for updates) under operational conditions.', 'HIGH', 'APPROVED', 'Critical for applications where low latency is a core requirement for correct function accomplishment.', 'ISO/IEC 25010:2023 - Time Behaviour', 'Excessive latency in real-time scenarios causes functional failures, safety risks, financial losses, or competitive disadvantage.'),
    ((SELECT id FROM category_sub WHERE short_name = 'TIM'), 'PEF-TIM-10', 'Performance Under Specified Conditions Compliance', 'All measured time behaviour metrics (response time, throughput) meet or exceed the quantified requirements defined for each load profile, environment, and condition in the performance specification.', 'HIGH', 'APPROVED', 'Provides overarching verification that time behaviour fully satisfies documented performance needs.', 'ISO/IEC 25010:2023 - Time Behaviour', 'Non-compliance leads to SLA violations, contractual penalties, user churn, or rejection during acceptance testing.');
INSERT INTO requirements
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((SELECT id FROM category_sub WHERE short_name = 'RUT'), 'PEF-RUT-01', 'CPU Utilization Under Nominal Load', 'Under nominal/expected load conditions, average CPU usage per core remains ≤ the specified threshold (e.g., < 70% sustained) during execution of key functions or workloads.', 'HIGH', 'APPROVED', 'Ensures the product uses CPU resources efficiently without excessive consumption under typical operation.', 'ISO/IEC 25010:2023 - Resource Utilization', 'High CPU usage leads to thermal throttling, reduced battery life (mobile), higher hosting costs, or inability to run concurrent processes.'),
    ((SELECT id FROM category_sub WHERE short_name = 'RUT'), 'PEF-RUT-02', 'Memory Consumption Compliance', 'Peak and steady-state memory (RAM) usage stays below defined limits (e.g., < 500 MB for baseline operations) across specified scenarios, with no memory leaks observed over prolonged runs.', 'HIGH', 'APPROVED', 'Verifies controlled memory footprint to prevent resource exhaustion.', 'ISO/IEC 25010:2023 - Resource Utilization', 'Excessive memory use causes out-of-memory errors, crashes, swapping/thrashing, degraded performance, or service outages.'),
    ((SELECT id FROM category_sub WHERE short_name = 'RUT'), 'PEF-RUT-03', 'Storage I/O and Disk Usage Efficiency', 'Disk read/write operations and temporary/permanent storage consumption remain within specified bounds (e.g., < X MB written per transaction, < Y GB total footprint) during normal and peak usage.', 'HIGH', 'APPROVED', 'Ensures efficient use of storage resources, critical for disk-bound or large-data applications.', 'ISO/IEC 25010:2023 - Resource Utilization', 'Overuse of disk I/O or space leads to slow performance, filling storage, increased cloud costs, or operational failures.'),
    ((SELECT id FROM category_sub WHERE short_name = 'RUT'), 'PEF-RUT-04', 'Network Bandwidth Utilization', 'Network traffic (inbound/outbound) for key operations stays ≤ specified rates (e.g., < 5 Mbps average during typical use) without unnecessary data transfer.', 'HIGH', 'APPROVED', 'Measures efficient network resource consumption, important for bandwidth-sensitive or mobile environments.', 'ISO/IEC 25010:2023 - Resource Utilization', 'Excessive bandwidth use increases data costs, slows networks for other users, or violates data caps in constrained environments.'),
    ((SELECT id FROM category_sub WHERE short_name = 'RUT'), 'PEF-RUT-05', 'Energy/Power Consumption Under Load', 'Power draw (e.g., watts or battery percentage per hour) remains below defined thresholds during idle, nominal, and peak operation on target hardware.', 'HIGH', 'APPROVED', 'Addresses energy efficiency as a resource, especially relevant for mobile, edge, or green IT requirements.', 'ISO/IEC 25010:2023 - Resource Utilization', 'High energy use shortens battery life, increases electricity/cloud costs, generates excess heat, or fails sustainability goals.'),
    ((SELECT id FROM category_sub WHERE short_name = 'RUT'), 'PEF-RUT-06', 'Resource Scaling with Load', 'Resource consumption (CPU, memory, etc.) scales acceptably (e.g., near-linear or sub-linear) as load increases from baseline to maximum specified levels.', 'HIGH', 'APPROVED', 'Confirms the product does not waste resources disproportionately under growing demand.', 'ISO/IEC 25010:2023 - Resource Utilization', 'Non-scalable resource growth leads to rapid exhaustion, higher provisioning needs, and cost overruns.'),
    ((SELECT id FROM category_sub WHERE short_name = 'RUT'), 'PEF-RUT-07', 'Idle Resource Consumption', 'When idle or in low-activity states, resource usage (CPU < 5%, memory baseline, network negligible) meets specified low-utilization requirements.', 'HIGH', 'APPROVED', 'Ensures minimal waste during non-active periods, critical for always-on services.', 'ISO/IEC 25010:2023 - Resource Utilization', 'High idle consumption wastes resources continuously, inflating operational costs and environmental impact.'),
    ((SELECT id FROM category_sub WHERE short_name = 'RUT'), 'PEF-RUT-08', 'Resource Leak Absence', 'Prolonged testing (e.g., 24+ hours under load) shows no progressive increase in resource usage (memory, file handles, threads) indicating leaks.', 'HIGH', 'APPROVED', 'Detects leaks that violate efficient resource use over time.', 'ISO/IEC 25010:2023 - Resource Utilization', 'Resource leaks cause gradual degradation, eventual crashes, or require restarts, reducing reliability and increasing maintenance.'),
    ((SELECT id FROM category_sub WHERE short_name = 'RUT'), 'PEF-RUT-09', 'Peak Resource Usage Under Stress', 'During stress/overload testing, resource consumption does not exceed hard limits (e.g., memory cap before OOM) and degrades gracefully.', 'HIGH', 'APPROVED', 'Verifies controlled behavior at resource boundaries.', 'ISO/IEC 25010:2023 - Resource Utilization', 'Uncontrolled spikes lead to system instability, crashes under load, or cascading failures in production.'),
    ((SELECT id FROM category_sub WHERE short_name = 'RUT'), 'PEF-RUT-10', 'Overall Resource Utilization Compliance', 'All profiled resource metrics (CPU, memory, storage, network, energy) across defined workloads and conditions meet or stay below the quantified requirements in the performance specification.', 'HIGH', 'APPROVED', 'Provides comprehensive verification of resource utilization efficiency.', 'ISO/IEC 25010:2023 - Resource Utilization', 'Non-compliance results in higher TCO, scalability issues, SLA breaches, or rejection in performance/acceptance testing.');
INSERT INTO requirements
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((SELECT id FROM category_sub WHERE short_name = 'CAP'), 'PEF-CAP-01', 'Maximum Concurrent Users / Sessions', 'The system supports the specified maximum number of concurrent users/sessions (e.g., ≥ 5,000 active sessions) without exceeding defined performance degradation thresholds or triggering failures.', 'HIGH', 'APPROVED', 'Verifies the system’s capacity to handle simultaneous users as required.', 'ISO/IEC 25010:2023 - Capacity', 'Exceeding capacity causes login failures, session drops, service unavailability, or degraded experience during peak usage periods.'),
    ((SELECT id FROM category_sub WHERE short_name = 'CAP'), 'PEF-CAP-02', 'Maximum Data Volume / Records Handled', 'The product can store, retrieve, and process the specified maximum data volume (e.g., ≥ 100 million records in primary tables, ≥ 10 TB total storage) while maintaining acceptable performance.', 'HIGH', 'APPROVED', 'Ensures capacity for data growth without structural or performance limits being hit prematurely.', 'ISO/IEC 25010:2023 - Capacity', 'Data growth beyond capacity leads to storage exhaustion, slow queries, indexing failures, or forced data purging/archiving.'),
    ((SELECT id FROM category_sub WHERE short_name = 'CAP'), 'PEF-CAP-03', 'Peak Transaction / Request Rate Capacity', 'The system sustains the specified peak transaction or request rate (e.g., ≥ 1,000 TPS) for a defined duration without errors, queuing beyond limits, or performance falling below SLAs.', 'HIGH', 'APPROVED', 'Tests the upper boundary of transaction-processing capacity under burst conditions.', 'ISO/IEC 25010:2023 - Capacity', 'Insufficient transaction capacity results in dropped requests, backlog buildup, lost revenue, or SLA violations during high-demand events.'),
    ((SELECT id FROM category_sub WHERE short_name = 'CAP'), 'PEF-CAP-04', 'Maximum Open Database Connections', 'The application and database layer support the required maximum number of concurrent open connections (e.g., ≥ 500) without connection pool exhaustion or timeouts.', 'HIGH', 'APPROVED', 'Confirms capacity for concurrent database interactions critical in multi-user systems.', 'ISO/IEC 25010:2023 - Capacity', 'Connection exhaustion causes application failures, “too many connections” errors, and widespread service disruption.'),
    ((SELECT id FROM category_sub WHERE short_name = 'CAP'), 'PEF-CAP-05', 'File / Attachment Storage Capacity', 'The system can handle the specified maximum number and total size of uploaded files/attachments (e.g., ≥ 1 million files, ≥ 5 TB total) without performance degradation or operational errors.', 'HIGH', 'APPROVED', 'Ensures capacity for content-heavy or document-centric applications.', 'ISO/IEC 25010:2023 - Capacity', 'Reaching file limits causes upload failures, storage quota errors, or degraded search/indexing performance.'),
    ((SELECT id FROM category_sub WHERE short_name = 'CAP'), 'PEF-CAP-06', 'Capacity Scaling with Horizontal Growth', 'Adding resources (e.g., nodes, instances) linearly increases supported capacity (users, TPS, data volume) up to the specified maximum scale-out target without diminishing returns.', 'HIGH', 'APPROVED', 'Verifies that architectural capacity can be extended predictably through scaling.', 'ISO/IEC 25010:2023 - Capacity', 'Poor scaling leads to unexpected capacity ceilings, expensive vertical upgrades, or inability to grow with business needs.'),
    ((SELECT id FROM category_sub WHERE short_name = 'CAP'), 'PEF-CAP-07', 'Maximum Queue / Message Backlog', 'Message queues, job queues, or async processing buffers can hold the specified maximum backlog (e.g., ≥ 100,000 pending messages) without overflow, loss, or unacceptable processing delay.', 'HIGH', 'APPROVED', 'Ensures capacity for handling temporary spikes in asynchronous workloads.', 'ISO/IEC 25010:2023 - Capacity', 'Queue overflow results in message loss, failed jobs, inconsistent state, or cascading system failures.'),
    ((SELECT id FROM category_sub WHERE short_name = 'CAP'), 'PEF-CAP-08', 'Cache / In-Memory Capacity', 'In-memory caches (e.g., Redis, Memcached) support the required maximum number of entries or total size (e.g., ≥ 10 million keys, ≥ 100 GB) with hit rates and eviction behavior meeting requirements.', 'HIGH', 'APPROVED', 'Tests capacity of caching layers to reduce load on backend systems.', 'ISO/IEC 25010:2023 - Capacity', 'Cache capacity limits cause frequent misses, increased backend load, higher latency, and potential hotspots.'),
    ((SELECT id FROM category_sub WHERE short_name = 'CAP'), 'PEF-CAP-09', 'Maximum API Rate Limit / Quota Capacity', 'The API layer sustains the defined maximum requests per second/minute per user, tenant, or globally (e.g., ≥ 10,000 RPM global) without artificial throttling beyond requirements.', 'HIGH', 'APPROVED', 'Verifies internal capacity before external rate-limiting kicks in.', 'ISO/IEC 25010:2023 - Capacity', 'Premature or insufficient capacity triggers excessive throttling, client errors (429), and degraded partner/integration experience.'),
    ((SELECT id FROM category_sub WHERE short_name = 'CAP'), 'PEF-CAP-10', 'Overall Capacity Requirements Compliance', 'All capacity-related metrics (concurrent users, data volume, TPS, connections, storage, etc.) across defined scenarios meet or exceed the quantified targets in the performance/capacity specification.', 'HIGH', 'APPROVED', 'Provides holistic verification that capacity fully satisfies documented business and technical requirements.', 'ISO/IEC 25010:2023 - Capacity', 'Capacity shortfalls lead to production incidents, inability to support growth, SLA breaches, customer churn, or costly emergency scaling.');
INSERT INTO requirements
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((SELECT id FROM category_sub WHERE short_name = 'COE'), 'COM-COE-01', 'No Detrimental Impact on Co-resident Applications', 'When installed and running alongside specified co-resident applications (e.g., antivirus, firewalls, other enterprise tools), the product causes no crashes, freezes, or functional degradation in those applications.', 'HIGH', 'APPROVED', 'Ensures the product does not harm other products sharing the environment, a core requirement of co-existence.', 'ISO/IEC 25010:2023 - Co-existence', 'Co-resident critical tools fail or become unstable, leading to system-wide outages, security gaps, or operational disruption.'),
    ((SELECT id FROM category_sub WHERE short_name = 'COE'), 'COM-COE-02', 'Resource Contention Absence Under Shared Load', 'Under concurrent operation with other specified products, resource usage (CPU, memory, disk I/O) does not cause the co-resident products to exceed their acceptable performance thresholds or trigger throttling.', 'HIGH', 'APPROVED', 'Verifies efficient sharing of resources without starving other applications.', 'ISO/IEC 25010:2023 - Co-existence', 'Other applications suffer slowdowns or failures due to resource starvation, resulting in poor multi-app user experience and support escalations.'),
    ((SELECT id FROM category_sub WHERE short_name = 'COE'), 'COM-COE-03', 'No Port or Network Conflict Issues', 'The product does not bind to ports, protocols, or network resources already in use by other specified co-resident products unless explicitly configured to share safely, and no conflicts cause failures in either product.', 'HIGH', 'APPROVED', 'Prevents network-level interference in shared environments like servers or desktops.', 'ISO/IEC 25010:2023 - Co-existence', 'Port conflicts lead to startup failures, communication breakdowns, or security vulnerabilities from forced overrides.'),
    ((SELECT id FROM category_sub WHERE short_name = 'COE'), 'COM-COE-04', 'File System and Registry Co-existence', 'Installation, operation, and uninstallation do not corrupt, overwrite, or lock shared files, registry keys, or configuration locations used by other products without proper isolation.', 'HIGH', 'APPROVED', 'Ensures safe sharing of persistent storage and configuration resources.', 'ISO/IEC 25010:2023 - Co-existence', 'Corrupted shared resources cause multiple applications to malfunction, data loss, or require manual recovery.'),
    ((SELECT id FROM category_sub WHERE short_name = 'COE'), 'COM-COE-05', 'Container / Virtualization Environment Compatibility', 'In containerized (Docker/Kubernetes) or virtualized environments (VMs), the product runs without causing pod/node instability, excessive resource contention, or eviction of co-resident containers/pods.', 'HIGH', 'APPROVED', 'Critical for cloud-native or virtualized deployments where multiple services share hosts.', 'ISO/IEC 25010:2023 - Co-existence', 'Container crashes or evictions disrupt entire clusters, leading to downtime and orchestration failures.'),
    ((SELECT id FROM category_sub WHERE short_name = 'COE'), 'COM-COE-06', 'No Driver or Kernel-Level Interference', 'On operating systems where applicable, the product installs/runs drivers, services, or kernel extensions without causing blue screens, kernel panics, or instability in co-resident drivers/services.', 'HIGH', 'APPROVED', 'Addresses low-level co-existence in OS environments with shared kernel resources.', 'ISO/IEC 25010:2023 - Co-existence', 'System crashes or instability affect the entire machine, creating high-severity incidents and loss of trust.'),
    ((SELECT id FROM category_sub WHERE short_name = 'COE'), 'COM-COE-07', 'Background Process / Service Co-existence', 'Background processes or services of the product do not interfere with scheduling, priority, or execution of background tasks from other products (e.g., no excessive polling or CPU hogging).', 'HIGH', 'APPROVED', 'Ensures non-disruptive background operation in multi-service environments.', 'ISO/IEC 25010:2023 - Co-existence', 'Other services experience degraded performance or missed schedules, impacting batch jobs or monitoring.'),
    ((SELECT id FROM category_sub WHERE short_name = 'COE'), 'COM-COE-08', 'Browser Extension or Plugin Co-existence', 'When applicable (e.g., web extensions), the product co-exists with other browser extensions without causing rendering issues, performance drops, or conflicting injections in shared browser instances.', 'HIGH', 'APPROVED', 'Tests co-existence in client-side shared environments like browsers.', 'ISO/IEC 25010:2023 - Co-existence', 'Browser instability or broken functionality affects user productivity across multiple extensions.'),
    ((SELECT id FROM category_sub WHERE short_name = 'COE'), 'COM-COE-09', 'No Logging or Monitoring Interference', 'The product does not flood shared logs, monitoring agents, or telemetry endpoints in a way that overwhelms or corrupts data from co-resident products.', 'HIGH', 'APPROVED', 'Prevents interference with shared observability resources.', 'ISO/IEC 25010:2023 - Co-existence', 'Overloaded logs or agents cause missed alerts, false positives, or inability to diagnose issues across applications.'),
    ((SELECT id FROM category_sub WHERE short_name = 'COE'), 'COM-COE-10', 'Overall Co-existence Compliance in Mixed Environments', 'In environments with a defined set of co-resident products (e.g., standard enterprise stack), all key functions perform efficiently with no measurable negative impact (crashes, >10% perf degradation, resource exhaustion) on any other product.', 'HIGH', 'APPROVED', 'Provides holistic verification of co-existence across representative shared setups.', 'ISO/IEC 25010:2023 - Co-existence', 'Unresolved co-existence issues lead to certification failures, deployment blocks, customer escalations, or prohibited use in enterprise environments.');
INSERT INTO requirements
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='INT'), 'COM-INT-03', 'Authentication Interoperability', 'The system shall support standard authentication mechanisms such as OAuth 2.0 or JWT for secure data exchange with external entities.', 'HIGH', 'APPROVED', 'Interoperable authentication ensures secure and standardized access control during information sharing.', 'ISO/IEC 25010:2011 - Compatibility.Interoperability', 'Security vulnerabilities from incompatible auth methods, leading to unauthorized access or integration failures.'),
    ((select id from category_sub where short_name='INT'), 'COM-INT-04', 'Error Handling Standardization', 'The system shall use standardized error codes and messages (e.g., HTTP status codes) when exchanging data to handle failures interoperably.', 'HIGH', 'APPROVED', 'Standardized error handling allows other systems to interpret and respond to issues consistently.', 'ISO/IEC 25010:2011 - Compatibility.Interoperability', 'Misinterpreted errors resulting in unresolved integration issues, prolonged downtime, and debugging challenges.'),
    ((select id from category_sub where short_name='INT'), 'COM-INT-05', 'Data Integrity During Exchange', 'The system shall ensure data integrity (e.g., via checksums or hashing) when exchanging information with other components.', 'HIGH', 'APPROVED', 'Maintaining data integrity prevents corruption and ensures usable exchanged information.', 'ISO/IEC 25010:2011 - Compatibility.Interoperability', 'Corrupted data leading to incorrect processing, system crashes, or compliance violations in integrated workflows.'),
    ((select id from category_sub where short_name='INT'), 'COM-INT-01', 'Standard Data Exchange Formats', 'The system shall support standard data formats such as JSON and XML for exchanging information with external systems or components.', 'HIGH', 'APPROVED', 'Using standard formats ensures seamless data exchange and reduces integration efforts with diverse systems.', 'ISO/IEC 25010:2011 - Compatibility.Interoperability', 'Data exchange failures leading to integration breakdowns, increased development costs, and inability to connect with third-party services.'),
    ((select id from category_sub where short_name='INT'), 'COM-INT-06', 'API Versioning Support', 'The system shall implement API versioning (e.g., via headers or URL paths) to maintain interoperability during updates.', 'HIGH', 'APPROVED', 'Versioning allows backward-compatible changes, ensuring ongoing exchange with legacy systems.', 'ISO/IEC 25010:2011 - Compatibility.Interoperability', 'Breaking changes causing integration disruptions, version conflicts, and forced upgrades for connected systems.'),
    ((select id from category_sub where short_name='INT'), 'COM-INT-07', 'Cross-Origin Resource Sharing (CORS)', 'The system shall configure CORS policies to allow secure data exchange with authorized external domains.', 'HIGH', 'APPROVED', 'CORS enables safe interoperability in web environments by controlling cross-origin requests.', 'ISO/IEC 25010:2011 - Compatibility.Interoperability', 'Blocked cross-origin requests leading to functionality loss in web integrations and user experience degradation.'),
    ((select id from category_sub where short_name='INT'), 'COM-INT-08', 'Encoding and Character Set Support', 'The system shall support multiple character encodings (e.g., UTF-8, UTF-16) for interoperable data exchange.', 'HIGH', 'APPROVED', 'Broad encoding support ensures accurate interpretation of international or special characters in exchanged data.', 'ISO/IEC 25010:2011 - Compatibility.Interoperability', 'Encoding mismatches causing garbled data, misinterpretation, and failures in global or multilingual integrations.'),
    ((select id from category_sub where short_name='INT'), 'COM-INT-09', 'Third-Party API Integration Testing', 'The system shall be tested for interoperability with at least three common third-party APIs (e.g., payment gateways, social logins).', 'HIGH', 'APPROVED', 'Real-world testing verifies practical interoperability beyond theoretical standards.', 'ISO/IEC 25010:2011 - Compatibility.Interoperability', 'Undiscovered integration issues leading to deployment failures, vendor lock-in, or operational disruptions.'),
    ((select id from category_sub where short_name='INT'), 'COM-INT-10', 'Asynchronous Messaging Compatibility', 'The system shall support standard asynchronous protocols (e.g., MQTT or AMQP) for event-driven interoperability if applicable.', 'HIGH', 'APPROVED', 'Asynchronous support enables efficient, non-blocking data exchange in distributed systems.', 'ISO/IEC 25010:2011 - Compatibility.Interoperability', 'Synchronous bottlenecks causing performance degradation, scalability limits, and unreliable event handling in integrations.'),
    ((select id from category_sub where short_name='INT'), 'COM-INT-02', 'Protocol Compatibility', 'The system shall support common communication protocols like HTTP/HTTPS, REST, or WebSockets for interoperability with other systems.', 'HIGH', 'APPROVED', 'Standard protocols facilitate reliable and efficient information exchange across heterogeneous environments.', 'ISO/IEC 25010:2011 - Compatibility.Interoperability', 'Communication mismatches causing connection errors, data loss during transmission, and limited scalability with partner systems.');
INSERT INTO requirements
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='ARE'), 'INC-ARE-01',  'Clear Action Affordance Labels', 'All interactive elements must include labels that clearly indicate the action they perform.', 'HIGH','APPROVED', 'Users must immediately understand what an element does to avoid hesitation or errors.', 'ISO/IEC 25010 – Appropriateness Recognizability', 'Users may trigger incorrect actions, leading to frustration and task abandonment.');  INSERT
    ((select id from category_sub where short_name='ARE'), 'INC-ARE-02',  'Consistent Iconography Usage',  'Icons used across the interface must follow consistent meaning and visual style.',  'HIGH','APPROVED',  'Consistency improves recognizability and reduces cognitive load.',  'ISO/IEC 25010 – Appropriateness Recognizability',  'Inconsistent icons cause misinterpretation and increase training/support costs.');  INSERT
    ((select id from category_sub where short_name='ARE'), 'INC-ARE-03',  'Context-Appropriate Terminology',  'Displayed terminology must match user domain language and avoid technical jargon.',  'HIGH','APPROVED',  'Users recognize actions faster when language aligns with their mental model.',  'ISO/IEC 25010 – Appropriateness Recognizability',  'Users may misunderstand tasks, leading to errors and reduced task completion rates.');  INSERT
    ((select id from category_sub where short_name='ARE'), 'INC-ARE-04',  'Predictable Navigation Structure',  'Navigation menus must follow a predictable structure that reflects user expectations.',  'HIGH','APPROVED',  'Predictability helps users quickly recognize where to find functions.',  'ISO/IEC 25010 – Appropriateness Recognizability',  'Users may become disoriented, increasing time to complete tasks.');  INSERT
    ((select id from category_sub where short_name='ARE'), 'INC-ARE-05',  'Task-Relevant UI Element Placement',  'UI elements must be placed near the content or task they relate to.',  'HIGH','APPROVED',  'Proximity improves recognizability and reduces scanning effort.',  'ISO/IEC 25010 – Appropriateness Recognizability',  'Users may overlook key actions, causing workflow interruptions.');  INSERT
    ((select id from category_sub where short_name='ARE'), 'INC-ARE-06',  'Immediate Visual Feedback on Interaction',  'Interactive elements must provide immediate visual feedback when hovered, focused, or clicked.',  'HIGH','APPROVED',  'Feedback helps users recognize which elements are interactive and confirms their actions.',  'ISO/IEC 25010 – Appropriateness Recognizability',  'Lack of feedback leads to repeated clicks, errors, and perceived system unresponsiveness.');  INSERT
    ((select id from category_sub where short_name='ARE'), 'INC-ARE-07',  'Clear Primary Action Differentiation',  'Primary actions must be visually distinguished from secondary or destructive actions.',  'HIGH','APPROVED',  'Users must instantly recognize the intended main action to avoid mistakes.',  'ISO/IEC 25010 – Appropriateness Recognizability',  'Users may select the wrong action, causing data loss or workflow disruption.');  INSERT
    ((select id from category_sub where short_name='ARE'), 'INC-ARE-08',  'Use of Standard Interaction Patterns',  'The interface must use standard, widely recognized interaction patterns where applicable.',  'HIGH','APPROVED',  'Familiar patterns reduce learning time and improve recognizability.',  'ISO/IEC 25010 – Appropriateness Recognizability',  'Non-standard patterns confuse users and increase training requirements.');  INSERT
    ((select id from category_sub where short_name='ARE'), 'INC-ARE-09',  'Visibility of Available Actions',  'All available actions relevant to the current task must be visible without requiring discovery.',  'HIGH','APPROVED',  'Users recognize appropriate actions faster when they are clearly visible.',  'ISO/IEC 25010 – Appropriateness Recognizability',  'Hidden actions lead to incomplete tasks and user frustration.');  INSERT
    ((select id from category_sub where short_name='ARE'), 'INC-ARE-10',  'Clear Error Message Purpose',  'Error messages must clearly indicate what went wrong and what action is appropriate.',  'HIGH','APPROVED',  'Recognizable error guidance helps users recover quickly.',  'ISO/IEC 25010 – Appropriateness Recognizability',  'Ambiguous errors cause user confusion, repeated failures, and support escalations.');
INSERT INTO requirements
    (category_sub_id, identifier,title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='LEA'), 'INC-LEA-001', 'Clear Onboarding Guidance', 'The system must provide concise onboarding instructions that help new users understand core tasks.', 'HIGH','APPROVED', 'Effective onboarding reduces initial learning time and increases user confidence.', 'ISO/IEC 25010 – Learnability', 'Users may feel overwhelmed and abandon the system,early.'),
    ((select id from category_sub where short_name='LEA'), 'INC-LEA-002', 'Progressive Disclosure of Features', 'Advanced features must be introduced gradually to avoid overwhelming new users.', 'HIGH','APPROVED', 'Progressive disclosure supports incremental learning and reduces cognitive load.', 'ISO/IEC 25010 – Learnability', 'Users may misuse advanced features or avoid them entirely.'),
    ((select id from category_sub where short_name='LEA'), 'INC-LEA-003', 'Consistent Interaction Patterns', 'The interface must use consistent layouts, controls, and interaction patterns across all screens.', 'HIGH','APPROVED', 'Consistency helps users transfer knowledge from one part of the system to another.', 'ISO/IEC 25010 – Learnability', 'Users may struggle to predict behavior, increasi,g training time and errors.'),
    ((select id from category_sub where short_name='LEA'), 'INC-LEA-004', 'Task-Oriented Help Content', 'Help content must be organized around user tasks rather than system features.', 'HIGH','APPROVED', 'Task-based guidance accelerates learning by aligning with user goals.', 'ISO/IEC 25010 – Learnability', 'Users may be unable to find relevant help, leading to frustration and support cal,s.'),
    ((select id from category_sub where short_name='LEA'), 'INC-LEA-005', 'Self-Explanatory Controls', 'Controls must be designed so their purpose is clear without requiring documentation.', 'HIGH','APPROVED', 'Self-explanatory controls reduce the need for training and trial-and-error.', 'ISO/IEC 25010 – Learnability', 'Users may rely on guesswork, increasing the likelihood of mistakes.'),
    ((select id from category_sub where short_name='LEA'), 'INC-LEA-006', 'Undo and Recovery Support', 'The system must provide easy-to-use undo or recovery options for reversible actions.', 'HIGH','APPROVED', 'Undo functionality encourages exploration and learning without fear of consequences.', 'ISO/IEC 25010 – Learnability', 'Users may avoid experimenting, slowing learning and increasing error severity.'),
    ((select id from category_sub where short_name='LEA'), 'INC-LEA-007', 'Minimal Steps for Core Tasks', 'Core user tasks must be achievable in the minimum number of steps without sacrificing clarity.', 'HIGH','APPROVED', 'Reducing unnecessary steps improves learnability and task efficiency.', 'ISO/IEC 25010 – Learnability', 'Users may struggle to complete tasks, incre,sing frustration and training needs.'),
    ((select id from category_sub where short_name='LEA'), 'INC-LEA-008', 'Predictable System Responses', 'System responses to user actions must be predictable and consistent.', 'HIGH','APPROVED', 'Predictability helps users form accurate mental models of system behavior.', 'ISO/IEC 25010 – Learnability', 'Unpredictable behavior increases confusion and slows learning.'),
    ((select id from category_sub where short_name='LEA'), 'INC-LEA-009', 'Inline Hints and Microlearning Cues', 'The interface must provide contextual hints or microlearning prompts during complex tasks.', 'HIGH','APPROVED', 'Inline guidance supports learning at the moment of need.', 'ISO/IEC 25010 – Learnability', 'Users may become stuck or perform tasks incorrectly without timely guidance.'),
    ((select id from category_sub where short_name='LEA'), 'INC-LEA-010', 'Recognition Over Recall', 'The system must prioritize recognition-based interactions (menus, icons, suggestions) over requiring users to remember commands.', 'HIGH','APPROVED', 'Recognition reduces cognitive effort and accelerates learning.', 'ISO/IEC 25010 – Learnability', 'Users may forget required steps, leading to errors and slower task completion.');
INSERT INTO requirements
  (category_sub_id, identifier,title, description, priority, status, rationale, source, risk_if_violated)
VALUES
  ((select id from category_sub where short_name='OPR'), 'INC-OPR-01', 'Simple and Efficient Task Execution', 'The system must allow users to complete common tasks with minimal steps and minimal cognitive effort.', 'HIGH','APPROVED', 'Reducing unnecessary steps improves operational efficiency and user satisfaction.', 'ISO/IEC 25010 – Operability', 'Users may become frustrated or abandon tasks due to excessive complexity.'),
  ((select id from category_sub where short_name='OPR'), 'INC-OPR-02', 'Clear and Accessible Controls', 'All controls must be clearly visible, appropriately sized, and easy to activate across devices.', 'HIGH','APPROVED', 'Accessible controls reduce operational errors and improve usability.', 'ISO/IEC 25010 – Operability', 'Users may struggle to interact with controls, leading to errors and reduced productivity.'),
  ((select id from category_sub where short_name='OPR'), 'INC-OPR-03', 'Consistent Control Behavior', 'Controls must behave consistently across the system, including hover, focus, and click interactions.', 'HIGH','APPROVED', 'Consistency helps users build reliable expectations and operate the system confidently.', 'ISO/IEC 25010 – Operability', 'Inconsistent behavior increases user confusion and operational mistakes.'),
  ((select id from category_sub where short_name='OPR'), 'INC-OPR-04', 'Support for User Preferences', 'The system must allow users to configure key operational settings such as notifications, layout, or shortcuts.', 'HIGH','APPROVED', 'Customization improves efficiency and accommodates diverse working styles.', 'ISO/IEC 25010 – Operability', 'Users may be forced into inefficient workflows, reducing overall effectiveness.'),
  ((select id from category_sub where short_name='OPR'), 'INC-OPR-05', 'Error Prevention Mechanisms', 'The system must include safeguards such as input validation, confirmation prompts, and constraints to prevent user errors.', 'HIGH','APPROVED', 'Preventing errors reduces operational risk and improves user confidence.', 'ISO/IEC 25010 – Operability', 'Users may make irreversible mistakes, leading to data loss or workflow disruption.'),
  ((select id from category_sub where short_name='OPR'), 'INC-OPR-06', 'Efficient Navigation Structure', 'Navigation must be intuitive, with clear pathways to frequently used features and minimal unnecessary depth.', 'HIGH','APPROVED', 'Efficient navigation reduces time spent searching for functions.', 'ISO/IEC 25010 – Operability', 'Users may waste time navigating, reducing productivity and increasing frustration.'),
  ((select id from category_sub where short_name='OPR'), 'INC-OPR-07', 'Immediate System Feedback', 'The system must provide immediate and clear feedback for all user actions, including loading indicators and success confirmations.', 'HIGH','APPROVED', 'Feedback reassures users that actions have been registered and reduces repeated inputs.', 'ISO/IEC 25010 – Operability', 'Lack of feedback may cause duplicate actions, errors, or perceived system failure.'),
  ((select id from category_sub where short_name='OPR'), 'INC-OPR-08', 'Support for Efficient Error Recovery', 'The system must provide clear instructions and tools to help users recover from errors quickly.', 'HIGH','APPROVED', 'Effective recovery reduces downtime and user frustration.', 'ISO/IEC 25010 – Operability', 'Users may become stuck or escalate issues unnecessarily, increasing support costs.'),
  ((select id from category_sub where short_name='OPR'), 'INC-OPR-09', 'Keyboard and Assistive Input Support', 'All interactive elements must be operable using keyboard navigation and assistive technologies.', 'HIGH','APPROVED', 'Supporting multiple input methods ensures operability for all users.', 'ISO/IEC 25010 – Operability', 'Users with accessibility needs may be unable to operate the system effectively.'),
  ((select id from category_sub where short_name='OPR'), 'INC-OPR-10', 'Clear System Status Visibility', 'The system must clearly display its current status, including processing states, connectivity, and mode changes.', 'HIGH','APPROVED', 'Visibility of system status helps users make informed operational decisions.', 'ISO/IEC 25010 – Operability', 'Users may misinterpret system behavior, leading to errors or unnecessary interruptions.');
INSERT INTO requirements
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='UEP'), 'INC-UEP-01',  'Input Validation at Point of Entry',  'The system must validate all user inputs immediately and provide clear guidance when values are invalid.',  'HIGH','APPROVED',  'Immediate validation prevents errors from propagating into later steps.',  'ISO/IEC 25010 – User Error Protection',  'Invalid data may cause task failure, data corruption, or user frustration.'),
    ((select id from category_sub where short_name='UEP'), 'INC-UEP-02', 'Confirmation for Destructive Actions', 'The system must require explicit confirmation before performing destructive or irreversible actions.', 'HIGH','APPROVED', 'Confirmation dialogs reduce the likelihood of accidental data loss.', 'ISO/IEC 25010 – User Error Protection', 'Users may unintentionally delete or modify critical data without a chance to recover.'),
    ((select id from category_sub where short_name='UEP'), 'INC-UEP-03',  'Prevent Submission of Incomplete Forms', 'Forms must prevent submission when required fields are missing or incomplete.', 'HIGH','APPROVED', 'Blocking incomplete submissions ensures data integrity and reduces rework.', 'ISO/IEC 25010 – User Error Protection', 'Incomplete or inconsistent data may enter the system, causing downstream failures.'),
    ((select id from category_sub where short_name='UEP'), 'INC-UEP-04', 'Contextual Error Messaging', 'Error messages must clearly describe the issue and provide actionable steps to resolve it.', 'HIGH','APPROVED', 'Clear guidance helps users recover quickly and reduces repeated mistakes.', 'ISO/IEC 25010 – User Error Protection', 'Ambiguous messages lead to confusion, repeated errors, and increased support needs.'),
    ((select id from category_sub where short_name='UEP'), 'INC-UEP-05',  'Prevention of Invalid Actions', 'The system must disable or hide actions that are not valid in the current context.', 'HIGH','APPROVED', 'Preventing invalid actions reduces the chance of user mistakes.', 'ISO/IEC 25010 – User Error Protection', 'Users may attempt unsupported actions, causing errors or workflow interruptions.'),
    ((select id from category_sub where short_name='UEP'), 'INC-UEP-06', 'Auto-Save and Draft Recovery', 'The system must automatically save user progress and allow recovery of unsaved work.', 'HIGH','APPROVED', 'Auto-save protects users from accidental data loss due to errors or interruptions.', 'ISO/IEC 25010 – User Error Protection', 'Users may lose significant work due to accidental navigation or system failures.'),
    ((select id from category_sub where short_name='UEP'), 'INC-UEP-07', 'Undo and Reversal Support', 'The system must provide undo functionality for reversible actions.', 'HIGH','APPROVED', 'Undo reduces the impact of mistakes and encourages exploration.', 'ISO/IEC 25010 – User Error Protection', 'Users may be unable to correct mistakes, leading to data errors or task abandonment.'),
    ((select id from category_sub where short_name='UEP'), 'INC-UEP-08', 'Pre-Filled Safe Defaults', 'Forms and settings must include safe, non-destructive default values.', 'HIGH','APPROVED', 'Safe defaults reduce the likelihood of harmful user choices.', 'ISO/IEC 25010 – User Error Protection', 'Users may unintentionally select harmful or suboptimal options, impacting system behavior.'),
    ((select id from category_sub where short_name='UEP'), 'INC-UEP-09', 'Real-Time Conflict Detection', 'The system must detect and warn users of conflicting inputs or actions before submission.', 'HIGH','APPROVED', 'Early detection prevents invalid states and reduces corrective work.', 'ISO/IEC 25010 – User Error Protection', 'Conflicting data may be submitted, causing system errors or workflow failures.'),
    ((select id from category_sub where short_name='UEP'), 'INC-UEP-10', 'Guided Correction Workflow', 'When an error occurs, the system must guide the user directly to the field or step requiring correction.', 'HIGH','APPROVED', 'Guided correction minimizes recovery time and reduces user frustration.', 'ISO/IEC 25010 – User Error Protection', 'Users may struggle to locate and fix errors, leading to task abandonment or repeated mistakes.');
INSERT INTO requirements
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='UEN'), 'INC-UEN-01', 'Visually Appealing Interface', 'The system must present a visually appealing interface with balanced layout, color harmony, and appropriate typography.', 'HIGH','APPROVED', 'Aesthetically pleasing interfaces increase user motivation and sustained engagement.', 'ISO/IEC 25010 – User Engagement', 'Users may perceive the system as outdated or untrustworthy, reducing willingness to use it.'),
    ((select id from category_sub where short_name='UEN'), 'INC-UEN-02', 'Interactive and Responsive UI Elements', 'UI elements must respond smoothly to user interactions with animations, transitions, or micro-interactions.', 'HIGH','APPROVED', 'Responsive interactions create a sense of control and satisfaction.', 'ISO/IEC 25010 – User Engagement', 'A static or unresponsive interface may feel dull, reducing user interest and retention.'),
	((select id from category_sub where short_name='UEN'), 'INC-UEN-03', 'Personalized User Experience', 'The system must adapt content or interface elements based on user preferences or behavior.', 'HIGH','APPROVED', 'Personalization increases relevance and emotional connection to the system.', 'ISO/IEC 25010 – User Engagement', 'Users may feel the system is generic or impersonal, reducing long-term engagement.'),
    ((select id from category_sub where short_name='UEN'), 'INC-UEN-04', 'Motivational Feedback and Rewards', 'The system must provide positive reinforcement such as progress indicators, achievements, or encouraging messages.', 'HIGH','APPROVED', 'Motivational feedback supports continued use and reinforces task completion.', 'ISO/IEC 25010 – User Engagement', 'Users may lose motivation and disengage from longer or complex tasks.'),
	((select id from category_sub where short_name='UEN'), 'INC-UEN-05', 'Clear and Engaging Content Presentation', 'Content must be presented in a clear, concise, and engaging manner using headings, visuals, and structured text.', 'HIGH','APPROVED', 'Engaging content improves comprehension and keeps users interested.', 'ISO/IEC 25010 – User Engagement', 'Poorly presented content may overwhelm or bore users, reducing task completion rates.'),
	((select id from category_sub where short_name='UEN'), 'INC-UEN-06', 'Support for Flow State', 'The system must minimize interruptions and distractions during focused tasks.', 'HIGH','APPROVED', 'Reducing interruptions helps users maintain concentration and engagement.', 'ISO/IEC 25010 – User Engagement', 'Frequent disruptions may break user focus, leading to frustration and abandonment.'),
	((select id from category_sub where short_name='UEN'), 'INC-UEN-07', 'Adaptive Difficulty or Guidance', 'The system must adjust guidance or task complexity based on user proficiency.', 'HIGH','APPROVED', 'Adaptive support keeps novice users engaged while avoiding boredom for experts.', 'ISO/IEC 25010 – User Engagement', 'Users may feel overwhelmed or under-challenged, reducing satisfaction and continued use.'),
	((select id from category_sub where short_name='UEN'), 'INC-UEN-08', 'Timely and Relevant Notifications', 'Notifications must be timely, relevant, and non-intrusive to maintain engagement without causing annoyance.', 'HIGH','APPROVED', 'Well-timed notifications re-engage users without overwhelming them.', 'ISO/IEC 25010 – User Engagement', 'Poorly timed or irrelevant notifications may cause disengagement or disablement of alerts.'),
	((select id from category_sub where short_name='UEN'), 'INC-UEN-09', 'Support for User Autonomy', 'The system must allow users to control pacing, navigation, and interaction flow.', 'HIGH','APPROVED', 'Autonomy increases user satisfaction and long-term engagement.', 'ISO/IEC 25010 – User Engagement', 'Users may feel constrained or controlled, reducing trust and willingness to continue using the system.'),
	((select id from category_sub where short_name='UEN'), 'INC-UEN-10', 'Emotionally Supportive Messaging', 'The system must use positive, empathetic, and encouraging language during interactions.', 'HIGH','APPROVED', 'Emotionally supportive communication strengthens user connection and reduces frustration.', 'ISO/IEC 25010 – User Engagement', 'Cold or discouraging messaging may increase user stress and reduce engagement.');
INSERT INTO requirements
    (category_sub_id, identifier,title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='INC'), 'INC-INC-01', 'Orientation', 'Content does not restrict its view and operation to a single display orientation (such as portrait or landscape), unless a specific display orientation is essential.', 'HIGH', 'APPROVED', 'Supports users of various ages and abilities (e.g., older users or those with motor impairments who prefer one orientation); promotes inclusivity across device usage habits and physical capabilities.', 'WCAG 2.2 - 1.3.4', 'Inclusivitity guidelines not met'),
    ((select id from category_sub where short_name='INC'), 'INC-INC-02', 'Identify Input Purpose', 'The purpose of each input field collecting information about the user can be programmatically determined when: (a) The input field serves a purpose identified in the Input Purposes for User Interface Components section; and (b) The content is implemented using technologies with support for identifying the expected meaning for form input data.', 'HIGH', 'APPROVED', 'Enables autofill for name, address, phone, etc., reducing barriers for users with cognitive disabilities, motor impairments, or language differences who struggle with manual entry.', 'WCAG 2.2 - 1.3.5', 'Inclusivitity guidelines not met'),
    ((select id from category_sub where short_name='INC'), 'INC-INC-03', 'Resize text', 'Except for captions and images of text, text can be resized up to 200 percent without loss of content or functionality.', 'HIGH', 'APPROVED', 'Supports low vision users and older adults with changing vision; essential for inclusivity across age and visual ability ranges.', 'WCAG 2.2 - 1.4.4', 'Inclusivitity guidelines not met'),
    ((select id from category_sub where short_name='INC'), 'INC-INC-04', 'Reflow', 'Content can be presented without loss of information or functionality, and without requiring scrolling in two dimensions for: (a) Vertical scrolling content at a width equivalent to 320 CSS pixels; (b) Horizontal scrolling content at a height equivalent to 256 CSS pixels.', 'HIGH', 'APPROVED', 'Critical for mobile/low-vision users and diverse device contexts; ensures content remains usable without horizontal scrolling for varied screen sizes and zoom levels.', 'WCAG 2.2 - 1.4.10', 'Inclusivitity guidelines not met'),
    ((select id from category_sub where short_name='INC'), 'INC-INC-05',  'Non-text Contrast', 'The visual presentation of the following have a contrast ratio of at least 3:1 against adjacent color(s): User Interface Components; Graphical Objects.', 'HIGH', 'APPROVED', 'Improves visibility for low-vision users, color-blind individuals, and older users with reduced contrast sensitivity.', 'WCAG 2.2 - 1.4.11', 'Inclusivitity guidelines not met'),
    ((select id from category_sub where short_name='INC'), 'INC-INC-06',  'Text Spacing', 'In content implemented using markup languages that support the following text style properties, no loss of content or functionality occurs by setting all of the following and by changing no other style property: Line height (line spacing) to at least 1.5 times the font size; Spacing following paragraphs to at least 2 times the font size; Letter spacing (tracking) to at least 0.12 times the font size; Word spacing to at least 0.16 times the font size.', 'HIGH', 'APPROVED', 'Prevents text overlap/cutoff when users override styles (common for dyslexia, low vision, or cognitive needs); supports diverse reading preferences and abilities.', 'WCAG 2.2 - 1.4.12', 'Inclusivitity guidelines not met'),
    ((select id from category_sub where short_name='INC'), 'INC-INC-07',  'Content on Hover or Focus', 'Additional content that becomes visible or hidden on hover or focus meets all of the following: Dismissible; Hoverable; Persistent (exceptions apply).', 'HIGH', 'APPROVED', 'Prevents popovers/tool-tips from blocking content for motor-impaired, keyboard, or touch users; enhances usability for varied interaction styles.', 'WCAG 2.2 - 1.4.13', 'Inclusivitity guidelines not met'),
    ((select id from category_sub where short_name='INC'), 'INC-INC-08',  'Pointer Gestures', 'All functionality that uses multipoint or path-based pointer gestures for operation can be operated with a single pointer without a path-based gesture (unless multipoint or path-based is essential).', 'MEDIUM', 'APPROVED', 'Supports users with motor disabilities or limited dexterity who struggle with pinch/rotate/drag gestures; promotes inclusivity for touch/mouse diversity.', 'WCAG 2.2 - 2.5.1', 'Inclusivitity guidelines not met'),
    ((select id from category_sub where short_name='INC'), 'INC-INC-09',  'Pointer Cancellation', 'For functionality that can be operated using a single pointer, at least one of the following is true: No Down-Event; Abort or Undo; Up Reversal (exceptions apply).', 'MEDIUM', 'APPROVED', 'Prevents accidental actions for users with tremors, limited motor control, or varied pointer precision.', 'WCAG 2.2 - 2.5.2', 'Inclusivitity guidelines not met'),
    ((select id from category_sub where short_name='INC'), 'INC-INC-10',  'Label in Name', 'For user interface components with labels that include text or images of text, the name contains the text that is presented visually.', 'MEDIUM', 'APPROVED', 'Ensures consistency for voice control/speech input users (e.g., cognitive or motor disabilities); critical for assistive tech inclusivity.', 'WCAG 2.2 - 2.5.3', 'Inclusivitity guidelines not met'),
    ((select id from category_sub where short_name='INC'), 'INC-INC-11',  'Motion Actuation', 'Functionality that can be operated by device motion or user motion can also be operated by user interface components and responding to the motion can be disabled (unless essential).', 'MEDIUM', 'APPROVED', 'Accommodates users who cannot perform gestures like shake/tilt due to motor or vestibular disabilities.', 'WCAG 2.2 - 2.5.4', 'Inclusivitity guidelines not met'),
    ((select id from category_sub where short_name='INC'), 'INC-INC-12',  'Target Size (Minimum)', 'The target size of pointer inputs is at least 24 by 24 CSS pixels, except where: Spacing; Inline; User agent control; Essential.', 'HIGH', 'APPROVED', 'Improves touch target usability for motor-impaired users, older adults, or those with reduced precision; enhances inclusivity on mobile/touch devices.', 'WCAG 2.2 - 2.5.8', 'Inclusivitity guidelines not met'),
    ((select id from category_sub where short_name='INC'), 'INC-INC-13',  'Dragging Movements', 'If functionality requires dragging movements, an alternative single-pointer method that does not use dragging is available (unless dragging is essential).', 'HIGH', 'APPROVED', 'Supports motor-impaired users who cannot reliably drag (e.g., sliders, carousels); broadens inclusivity for interaction diversity.', 'WCAG 2.2 - 2.5.7', 'Inclusivitity guidelines not met'),
    ((select id from category_sub where short_name='INC'), 'INC-INC-14',  'Accessible Authentication (Minimum)', 'A cognitive function test (such as remembering a password or solving a puzzle) is not required for any step in an authentication process unless that step provides an alternative that does not rely on a cognitive function test, or provides at least one of: object recognition with descriptions; personal content mechanisms.', 'HIGH', 'APPROVED', 'Reduces barriers for users with cognitive disabilities, learning disabilities, or age-related memory issues; directly promotes inclusivity across cognitive diversity.', 'WCAG 2.2 - 3.3.8', 'Inclusivitity guidelines not met'),
    ((select id from category_sub where short_name='INC'), 'INC-INC-15',  'Redundant Entry', 'When information is required to be entered by the user in the same or similar context, it is either: auto-populated; or available for the user to select (exceptions for re-entering passwords, security, essential data).', 'MEDIUM', 'APPROVED', 'Reduces cognitive and typing burden for users with disabilities, older adults, or language barriers; supports repeated form entry inclusively.', 'WCAG 2.2 - 3.3.7', 'Inclusivitity guidelines not met');
INSERT INTO requirements
  (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='UAS'), 'INC-UAS-01', 'Provide Clear Instructions for Inputs', 'The system must provide clear instructions, examples, or labels for all user inputs, especially when specific formats or constraints are required.', 'HIGH','APPROVED', 'Clear instructions reduce user confusion and prevent input errors.', 'WCAG 2.2 – 3.3.2 Labels or Instructions', 'Users may enter incorrect data, causing task failure or frustration.'),
	((select id from category_sub where short_name='UAS'), 'INC-UAS-02', 'Provide Error Identification', 'When an error occurs, the system must identify the specific field or action that caused the error.', 'HIGH','APPROVED', 'Identifying the exact error helps users correct mistakes quickly.', 'WCAG 2.2 – 3.3.1 Error Identification', 'Users may be unable to determine what went wrong, leading to task abandonment.'),
	((select id from category_sub where short_name='UAS'), 'INC-UAS-03', 'Provide Error Correction Suggestions', 'The system must offer suggestions or guidance to help users correct input errors.', 'HIGH','APPROVED', 'Actionable suggestions reduce cognitive load and improve task success.', 'WCAG 2.2 – 3.3.3 Error Suggestion', 'Users may repeatedly make the same mistakes, increasing frustration and support needs.'),
	((select id from category_sub where short_name='UAS'), 'INC-UAS-04', 'Provide Confirmation for Critical Actions', 'The system must require confirmation before performing critical or irreversible actions.', 'HIGH','APPROVED', 'Confirmation dialogs protect users from accidental destructive actions.', 'WCAG 2.2 – 3.3.4 Error Prevention (Legal, Financial, Data)', 'Users may unintentionally perform irreversible actions, causing data loss or compliance issues.'),
	((select id from category_sub where short_name='UAS'), 'INC-UAS-05', 'Provide Accessible Help Mechanisms', 'The system must provide accessible help options such as tooltips, help text, or contextual assistance.', 'HIGH','APPROVED', 'Accessible help improves user confidence and reduces dependency on external support.', 'WCAG 2.2 – 3.3.5 Help', 'Users may struggle to complete tasks without guidance, increasing error rates.'),
	((select id from category_sub where short_name='UAS'), 'INC-UAS-06', 'Provide Consistent and Predictable Navigation', 'Navigation elements must remain consistent across the system to support user orientation.', 'HIGH','APPROVED', 'Predictable navigation reduces cognitive load and supports task completion.', 'WCAG 2.2 – 3.2.3 Consistent Navigation', 'Users may become disoriented, leading to errors and reduced efficiency.'),
	((select id from category_sub where short_name='UAS'), 'INC-UAS-07', 'Provide Consistent Component Behavior', 'Interactive components must behave consistently across the system.', 'HIGH','APPROVED', 'Consistency helps users form accurate expectations and reduces learning time.', 'WCAG 2.2 – 3.2.4 Consistent Identification', 'Users may misinterpret controls, leading to operational mistakes.'),
	((select id from category_sub where short_name='UAS'), 'INC-UAS-08', 'Provide Time Extension for Time-Limited Tasks', 'Users must be able to extend or disable time limits unless essential to system function.', 'HIGH','APPROVED', 'Time extensions support users who need more time due to cognitive or physical constraints.', 'WCAG 2.2 – 2.2.1 Timing Adjustable', 'Users may lose progress or fail tasks due to insufficient time.'),
	((select id from category_sub where short_name='UAS'), 'INC-UAS-09', 'Provide Clear Focus Indicators', 'Interactive elements must have visible focus indicators to assist keyboard and assistive technology users.', 'HIGH','APPROVED', 'Clear focus indicators help users understand where they are in the interface.', 'WCAG 2.2 – 2.4.7 Focus Visible', 'Users may activate the wrong control or become lost during navigation.'),
	((select id from category_sub where short_name='UAS'), 'INC-UAS-10', 'Provide Accessible Instructions for Complex Tasks', 'The system must provide step-by-step guidance or breakdowns for multi-step or complex tasks.', 'HIGH','APPROVED', 'Guidance reduces cognitive load and supports successful task completion.', 'WCAG 2.2 – 3.3.6 Accessible Authentication / Task Assistance', 'Users may fail to complete complex tasks, leading to abandonment or errors.');
INSERT INTO requirements
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='SDE'), 'INC-SDE-01', 'Clear Purpose of Each Screen', 'Each screen must clearly communicate its purpose through headings, summaries, or contextual cues.', 'HIGH','APPROVED', 'Users understand what they can accomplish without needing external guidance.', 'ISO/IEC 25010 – Self-descriptiveness', 'Users may become confused about the intent of the screen, leading to errors or abandonment.'),
	((select id from category_sub where short_name='SDE'), 'INC-SDE-02', 'Descriptive Labels for All Controls', 'All interactive controls must have descriptive labels that clearly indicate their function.', 'HIGH','APPROVED', 'Descriptive labels reduce ambiguity and support intuitive use.', 'ISO/IEC 25010 – Self-descriptiveness', 'Users may misinterpret controls and perform unintended actions.'),
	((select id from category_sub where short_name='SDE'), 'INC-SDE-03', 'Contextual Help Availability', 'The system must provide contextual help or tooltips explaining complex fields or actions.', 'HIGH','APPROVED', 'Contextual help reduces reliance on external documentation.', 'ISO/IEC 25010 – Self-descriptiveness', 'Users may struggle to understand system functions, increasing support needs.'),
	((select id from category_sub where short_name='SDE'), 'INC-SDE-04', 'Visible System Status Indicators', 'The system must clearly display its current status, including loading, saving, or processing states.', 'HIGH','APPROVED', 'Visible status indicators help users understand what the system is doing.', 'ISO/IEC 25010 – Self-descriptiveness', 'Users may assume the system is unresponsive, leading to repeated actions or errors.'),
	((select id from category_sub where short_name='SDE'), 'INC-SDE-05', 'Meaningful Error Messages', 'Error messages must clearly describe the issue and provide guidance for resolution.', 'HIGH','APPROVED', 'Clear error messages support user understanding and recovery.', 'ISO/IEC 25010 – Self-descriptiveness', 'Users may be unable to correct issues, causing task failure or frustration.'),
	((select id from category_sub where short_name='SDE'), 'INC-SDE-06', 'Self-Explanatory Navigation Structure', 'Navigation elements must clearly indicate their destination or function.', 'HIGH','APPROVED', 'Clear navigation supports intuitive exploration and reduces cognitive load.', 'ISO/IEC 25010 – Self-descriptiveness', 'Users may become lost or unable to locate needed functions.'),
	((select id from category_sub where short_name='SDE'), 'INC-SDE-07', 'Immediate Feedback on User Actions', 'The system must provide immediate and understandable feedback for all user actions.', 'HIGH','APPROVED', 'Feedback helps users understand the outcome of their actions.', 'ISO/IEC 25010 – Self-descriptiveness', 'Users may repeat actions unnecessarily or assume the system is malfunctioning.'),
	((select id from category_sub where short_name='SDE'), 'INC-SDE-08', 'Clear Indication of Required Fields', 'Required fields must be clearly marked and accompanied by explanatory text when needed.', 'HIGH','APPROVED', 'Clear indicators help users understand what information is necessary.', 'ISO/IEC 25010 – Self-descriptiveness', 'Users may submit incomplete forms, causing errors or workflow delays.'),
	((select id from category_sub where short_name='SDE'), 'INC-SDE-09', 'Descriptive Page Titles and Headings', 'Page titles and headings must accurately reflect the content and purpose of the page.', 'HIGH','APPROVED', 'Accurate headings support orientation and comprehension.', 'ISO/IEC 25010 – Self-descriptiveness', 'Users may misunderstand page content, leading to navigation errors.'),
	((select id from category_sub where short_name='SDE'), 'INC-SDE-10', 'Clear Task Progress Indicators', 'The system must provide clear indicators of task progress, such as step numbers or progress bars.', 'HIGH','APPROVED', 'Progress indicators help users understand where they are in a process.', 'ISO/IEC 25010 – Self-descriptiveness', 'Users may feel uncertain or abandon tasks due to lack of clarity.');
INSERT INTO requirements
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
	((select id from category_sub where short_name='FAU'), 'REL-FAU-01', 'Consistent System Responses', 'The system must produce consistent and repeatable responses for identical user inputs and conditions.', 'HIGH','APPROVED', 'Consistency ensures reliability and prevents user confusion.', 'ISO/IEC 25010 – Faultlessness', 'Inconsistent behavior may lead to mistrust, errors, and unpredictable outcomes.'),
    ((select id from category_sub where short_name='FAU'), 'REL-FAU-02', 'Error-Free Data Processing', 'All data processing operations must execute without producing incorrect, partial, or corrupted results.', 'HIGH','APPROVED', 'Accurate processing is essential for reliable system operation.', 'ISO/IEC 25010 – Faultlessness', 'Faulty processing may lead to data loss, incorrect outputs, or system instability.'),
	((select id from category_sub where short_name='FAU'), 'REL-FAU-03', 'Robust Input Handling', 'The system must handle all valid inputs correctly and reject invalid inputs gracefully.', 'HIGH','APPROVED', 'Robust input handling prevents unexpected failures and improves reliability.', 'ISO/IEC 25010 – Faultlessness', 'Invalid inputs may cause crashes, data corruption, or security vulnerabilities.'),
	((select id from category_sub where short_name='FAU'), 'REL-FAU-04', 'Reliable State Management', 'The system must maintain accurate and consistent internal state across interactions.', 'HIGH','APPROVED', 'Correct state management ensures predictable system behavior.', 'ISO/IEC 25010 – Faultlessness', 'State inconsistencies may cause incorrect results or workflow failures.'),
	((select id from category_sub where short_name='FAU'), 'REL-FAU-05', 'No Dead-End Interactions', 'All user interactions must lead to a valid next step or provide clear recovery options.', 'HIGH','APPROVED', 'Avoiding dead ends ensures smooth task progression.', 'ISO/IEC 25010 – Faultlessness', 'Users may become stuck, abandon tasks, or assume the system is broken.'),
	((select id from category_sub where short_name='FAU'), 'REL-FAU-06', 'Accurate System Feedback', 'Feedback messages must accurately reflect the system’s actual status and outcomes.', 'HIGH','APPROVED', 'Accurate feedback helps users make correct decisions.', 'ISO/IEC 25010 – Faultlessness', 'Incorrect feedback may mislead users, causing errors or data issues.'),
	((select id from category_sub where short_name='FAU'), 'REL-FAU-07', 'Reliable Transaction Completion', 'All multi-step transactions must complete fully or roll back cleanly in case of failure.', 'HIGH','APPROVED', 'Reliable transactions prevent partial or inconsistent system states.', 'ISO/IEC 25010 – Faultlessness', 'Partial transactions may corrupt data or disrupt workflows.'),
	((select id from category_sub where short_name='FAU'), 'REL-FAU-08', 'No Unexpected System Behavior', 'The system must not exhibit unexpected or undocumented behavior during normal use.', 'HIGH','APPROVED', 'Predictability is essential for user trust and operational reliability.', 'ISO/IEC 25010 – Faultlessness', 'Unexpected behavior may cause user errors or system misuse.'),
	((select id from category_sub where short_name='FAU'), 'REL-FAU-09', 'Reliable Error Logging', 'All system errors must be logged accurately with sufficient detail for diagnosis.', 'HIGH','APPROVED', 'Reliable logging supports fault detection and correction.', 'ISO/IEC 25010 – Faultlessness', 'Missing or inaccurate logs hinder troubleshooting and prolong outages.'),
	((select id from category_sub where short_name='FAU'), 'REL-FAU-10', 'Correct Execution of User Commands', 'The system must execute user commands exactly as specified without unintended side effects.', 'HIGH','APPROVED', 'Correct execution ensures user trust and prevents operational errors.', 'ISO/IEC 25010 – Faultlessness', 'Incorrect execution may lead to data corruption, workflow disruption, or safety risks.');
INSERT INTO requirements
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='AVA'), 'REL-AVA-01', 'High System Uptime', 'The system must maintain a minimum uptime threshold aligned with service-level expectations (e.g., 99.9%).', 'HIGH','APPROVED', 'High availability ensures users can reliably access the system when needed.', 'ISO/IEC 25010 – Availability', 'Frequent downtime disrupts operations and reduces user trust.'),
	((select id from category_sub where short_name='AVA'), 'REL-AVA-02', 'Redundant Critical Components', 'Critical system components must include redundancy to prevent single points of failure.', 'HIGH','APPROVED', 'Redundancy increases resilience and reduces service interruptions.', 'ISO/IEC 25010 – Availability', 'A single component failure may cause full system outages.'),
	((select id from category_sub where short_name='AVA'), 'REL-AVA-03', 'Automatic Failover Mechanisms', 'The system must automatically switch to backup components or services when failures occur.', 'HIGH','APPROVED', 'Automatic failover minimizes downtime and maintains service continuity.', 'ISO/IEC 25010 – Availability', 'Manual recovery increases outage duration and operational risk.'),
	((select id from category_sub where short_name='AVA'), 'REL-AVA-04', 'Graceful Degradation', 'The system must continue to provide essential functionality even when non-critical components fail.', 'HIGH','APPROVED', 'Graceful degradation preserves core user capabilities during partial failures.', 'ISO/IEC 25010 – Availability', 'Users may experience complete service loss even when only minor components fail.'),
	((select id from category_sub where short_name='AVA'), 'REL-AVA-05', 'Real-Time Health Monitoring', 'The system must continuously monitor component health and detect availability issues in real time.', 'HIGH','APPROVED', 'Monitoring enables early detection and rapid response to failures.', 'ISO/IEC 25010 – Availability', 'Undetected failures may escalate into prolonged outages.'),
	((select id from category_sub where short_name='AVA'), 'REL-AVA-06', 'Predictable Maintenance Windows', 'Scheduled maintenance must be communicated in advance and occur during low-impact periods.', 'HIGH','APPROVED', 'Predictable maintenance minimizes user disruption and maintains trust.', 'ISO/IEC 25010 – Availability', 'Unexpected downtime may interrupt critical user activities.'),
	((select id from category_sub where short_name='AVA'), 'REL-AVA-07', 'Fast Recovery Time Objective (RTO)', 'The system must recover from failures within a defined maximum recovery time.', 'HIGH','APPROVED', 'Short RTO ensures rapid restoration of service after disruptions.', 'ISO/IEC 25010 – Availability', 'Long recovery times may halt operations and cause significant productivity loss.'),
	((select id from category_sub where short_name='AVA'), 'REL-AVA-08', 'Load Handling Without Service Interruption', 'The system must maintain availability under expected and peak load conditions.', 'HIGH','APPROVED', 'Proper load handling prevents outages during high-demand periods.', 'ISO/IEC 25010 – Availability', 'System overload may cause crashes or severe performance degradation.'),
	((select id from category_sub where short_name='AVA'), 'REL-AVA-09', 'Network Resilience', 'The system must tolerate transient network failures and automatically retry or reconnect.', 'HIGH','APPROVED', 'Network resilience ensures continuous operation despite connectivity issues.', 'ISO/IEC 25010 – Availability', 'Minor network disruptions may cause full session loss or user lockout.'),
	((select id from category_sub where short_name='AVA'), 'REL-AVA-10', 'Service Status Transparency', 'The system must provide users with clear and timely information about service availability or outages.', 'HIGH','APPROVED', 'Transparency helps users make informed decisions and reduces frustration.', 'ISO/IEC 25010 – Availability', 'Users may assume the system is malfunctioning or unreliable without clear status updates.');
INSERT INTO requirements
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='FTO'), 'REL-FTO-01', 'Graceful Handling of Component Failures', 'The system must continue operating at reduced capacity when non-critical components fail.', 'HIGH','APPROVED', 'Graceful degradation ensures continuity of service during partial failures.', 'ISO/IEC 25010 – Fault Tolerance', 'Users may experience full service outages due to minor component failures.'),
    ((select id from category_sub where short_name='FTO'), 'REL-FTO-02', 'Automatic Retry for Transient Errors', 'The system must automatically retry operations that fail due to transient issues such as network instability.', 'HIGH','APPROVED', 'Automatic retries prevent unnecessary failures and improve reliability.', 'ISO/IEC 25010 – Fault Tolerance', 'Users may encounter avoidable errors, reducing trust in the system.'),
    ((select id from category_sub where short_name='FTO'), 'REL-FTO-03', 'Fail-Safe Defaults', 'The system must revert to safe default states when unexpected conditions occur.', 'HIGH','APPROVED', 'Fail-safe defaults minimize the impact of faults and prevent unsafe behavior.', 'ISO/IEC 25010 – Fault Tolerance', 'Unexpected conditions may lead to unsafe or unpredictable system behavior.'),
    ((select id from category_sub where short_name='FTO'), 'REL-FTO-04', 'Transaction Integrity Under Failure', 'Transactions must either complete fully or roll back cleanly when faults occur.', 'HIGH','APPROVED', 'Maintaining transaction integrity prevents data corruption.', 'ISO/IEC 25010 – Fault Tolerance', 'Partial transactions may leave the system in an inconsistent or corrupted state.'),
    ((select id from category_sub where short_name='FTO'), 'REL-FTO-05', 'Redundant Execution Paths', 'Critical operations must have redundant execution paths to ensure continuity during failures.', 'HIGH','APPROVED', 'Redundancy increases resilience and reduces downtime.', 'ISO/IEC 25010 – Fault Tolerance', 'A single failure may halt critical operations entirely.'),
    ((select id from category_sub where short_name='FTO'), 'REL-FTO-06', 'Error Isolation Mechanisms', 'The system must isolate faults to prevent them from propagating to other components.', 'HIGH','APPROVED', 'Isolation limits the scope and impact of failures.', 'ISO/IEC 25010 – Fault Tolerance', 'A small fault may cascade into a system-wide outage.'),
    ((select id from category_sub where short_name='FTO'), 'REL-FTO-07', 'State Preservation During Failures', 'The system must preserve user and system state during recoverable failures.', 'HIGH','APPROVED', 'State preservation enables smooth recovery and prevents data loss.', 'ISO/IEC 25010 – Fault Tolerance', 'Users may lose progress or encounter inconsistent states after failures.'),
    ((select id from category_sub where short_name='FTO'), 'REL-FTO-08', 'Fallback to Alternative Services', 'When primary services fail, the system must automatically switch to alternative or backup services.', 'HIGH','APPROVED', 'Fallback mechanisms maintain service continuity during outages.', 'ISO/IEC 25010 – Fault Tolerance', 'Users may experience complete service disruption when alternatives exist.'),
    ((select id from category_sub where short_name='FTO'), 'REL-FTO-09', 'Detection and Recovery from Hung Processes', 'The system must detect hung or stalled processes and recover automatically.', 'HIGH','APPROVED', 'Automatic recovery prevents long-running failures and improves uptime.', 'ISO/IEC 25010 – Fault Tolerance', 'Hung processes may degrade performance or cause full system outages.'),
    ((select id from category_sub where short_name='FTO'), 'REL-FTO-10', 'Consistent Behavior Under Partial Failure', 'The system must maintain predictable behavior even when some components are degraded.', 'HIGH','APPROVED', 'Predictability under failure conditions supports user trust and operational stability.', 'ISO/IEC 25010 – Fault Tolerance', 'Users may encounter erratic or unsafe behavior during partial failures.');
INSERT INTO requirements
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='REC'), 'REL-REC-01', 'Automatic Recovery from System Failures', 'The system must automatically recover from unexpected failures without requiring user intervention.', 'HIGH','APPROVED', 'Automatic recovery minimizes downtime and preserves user productivity.', 'ISO/IEC 25010 – Recoverability', 'Users may experience prolonged outages or lose work due to manual recovery delays.'),
	((select id from category_sub where short_name='REC'), 'REL-REC-02', 'Session Restoration After Failure', 'The system must restore the user’s session state after a crash or unexpected interruption.', 'HIGH','APPROVED', 'Session restoration prevents loss of progress and reduces frustration.', 'ISO/IEC 25010 – Recoverability', 'Users may lose significant work and be forced to restart tasks from the beginning.'),
	((select id from category_sub where short_name='REC'), 'REL-REC-03', 'Data Integrity Verification After Recovery', 'The system must verify data integrity after recovery and notify users of any inconsistencies.', 'HIGH','APPROVED', 'Integrity checks ensure recovered data is accurate and trustworthy.', 'ISO/IEC 25010 – Recoverability', 'Corrupted data may go undetected, leading to incorrect outputs or decisions.'),
	((select id from category_sub where short_name='REC'), 'REL-REC-04', 'Clear Recovery Instructions', 'The system must provide clear, actionable instructions to users when manual recovery steps are required.', 'HIGH','APPROVED', 'Clear instructions reduce recovery time and prevent user errors.', 'ISO/IEC 25010 – Recoverability', 'Users may perform incorrect recovery steps, worsening the failure state.'),
	((select id from category_sub where short_name='REC'), 'REL-REC-05', 'Automatic Reconnection After Network Loss', 'The system must automatically reconnect and resume operations after temporary network disruptions.', 'HIGH','APPROVED', 'Automatic reconnection ensures continuity and reduces user frustration.', 'ISO/IEC 25010 – Recoverability', 'Users may lose progress or be forced to restart workflows after minor network issues.'),
	((select id from category_sub where short_name='REC'), 'REL-REC-06', 'Rollback to Last Known Good State', 'The system must support rolling back to the last known good state when recovery fails.', 'HIGH','APPROVED', 'Rollback mechanisms prevent prolonged outages and data corruption.', 'ISO/IEC 25010 – Recoverability', 'The system may remain in an unstable or unusable state after a failure.'),
	((select id from category_sub where short_name='REC'), 'REL-REC-07', 'Recovery Time Objective (RTO) Compliance', 'The system must meet defined recovery time objectives for all critical components.', 'HIGH','APPROVED', 'Meeting RTO ensures predictable and acceptable recovery performance.', 'ISO/IEC 25010 – Recoverability', 'Extended recovery times may disrupt operations and violate service-level agreements.'),
	((select id from category_sub where short_name='REC'), 'REL-REC-08', 'Recovery Point Objective (RPO) Compliance', 'The system must ensure that data loss during recovery does not exceed the defined recovery point objective.', 'HIGH','APPROVED', 'RPO compliance limits data loss to acceptable thresholds.', 'ISO/IEC 25010 – Recoverability', 'Users may lose critical data beyond acceptable limits, impacting business continuity.'),
	((select id from category_sub where short_name='REC'), 'REL-REC-09', 'User Notification of Recovery Status', 'The system must notify users when recovery is in progress and when it is complete.', 'HIGH','APPROVED', 'Status notifications keep users informed and reduce uncertainty.', 'ISO/IEC 25010 – Recoverability', 'Users may assume the system is unresponsive or malfunctioning during recovery.'),
	((select id from category_sub where short_name='REC'), 'REL-REC-10', 'Preservation of Critical Logs During Failure', 'The system must preserve diagnostic logs during failures to support accurate recovery and troubleshooting.', 'HIGH','APPROVED', 'Preserved logs enable effective root-cause analysis and faster recovery.', 'ISO/IEC 25010 – Recoverability', 'Missing logs may hinder diagnosis, prolonging outages and increasing recurrence risk.');
INSERT INTO requirements
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='CON'), 'SEC-CON-01', 'Role-Based Access Control', 'The system must restrict access to sensitive data based on user roles and permissions.', 'HIGH','APPROVED', 'RBAC ensures users only access information necessary for their responsibilities.', 'ISO/IEC 25010 – Confidentiality', 'Unauthorized users may gain access to sensitive or regulated information.'),
    ((select id from category_sub where short_name='CON'), 'SEC-CON-02', 'Encryption of Data in Transit', 'All sensitive data transmitted between system components must be encrypted using industry-standard protocols.', 'HIGH','APPROVED', 'Encryption prevents interception and unauthorized disclosure during transmission.', 'ISO/IEC 25010 – Confidentiality', 'Attackers may intercept unencrypted data, exposing sensitive information.'),
    ((select id from category_sub where short_name='CON'), 'SEC-CON-03', 'Encryption of Data at Rest', 'Sensitive data stored in databases, logs, or backups must be encrypted at rest.', 'HIGH','APPROVED', 'Encryption protects data even if storage media is compromised.', 'ISO/IEC 25010 – Confidentiality', 'A breach of storage systems may expose unencrypted sensitive data.'),
    ((select id from category_sub where short_name='CON'), 'SEC-CON-04', 'Secure Session Management', 'User sessions must be protected using secure tokens, expiration policies, and regeneration on privilege changes.', 'HIGH','APPROVED', 'Secure sessions prevent unauthorized access through session hijacking.', 'ISO/IEC 25010 – Confidentiality', 'Attackers may impersonate users by exploiting weak session controls.'),
    ((select id from category_sub where short_name='CON'), 'SEC-CON-05', 'Least Privilege Enforcement', 'Users and system components must operate with the minimum privileges required to perform their tasks.', 'HIGH','APPROVED', 'Least privilege reduces the attack surface and limits damage from compromised accounts.', 'ISO/IEC 25010 – Confidentiality', 'Excessive permissions may allow unauthorized access to sensitive data.'),
    ((select id from category_sub where short_name='CON'), 'SEC-CON-06', 'Protection Against Data Leakage', 'The system must prevent accidental or unauthorized exposure of sensitive data through logs, error messages, or UI elements.', 'HIGH','APPROVED', 'Preventing leakage ensures sensitive data is not exposed unintentionally.', 'ISO/IEC 25010 – Confidentiality', 'Sensitive information may be revealed through overlooked channels.'),
    ((select id from category_sub where short_name='CON'), 'SEC-CON-07', 'Multi-Factor Authentication for Sensitive Access', 'Access to sensitive data or administrative functions must require multi-factor authentication.', 'HIGH','APPROVED', 'MFA significantly reduces the risk of unauthorized access.', 'ISO/IEC 25010 – Confidentiality', 'Compromised credentials may allow attackers to access sensitive data.'),
    ((select id from category_sub where short_name='CON'), 'SEC-CON-08', 'Secure Storage of Credentials', 'All credentials, tokens, and secrets must be stored using secure hashing or secret‑management systems.', 'HIGH','APPROVED', 'Secure storage prevents credential theft and unauthorized access.', 'ISO/IEC 25010 – Confidentiality', 'Plaintext or weakly protected credentials may be stolen and exploited.'),
    ((select id from category_sub where short_name='CON'), 'SEC-CON-09', 'Access Logging and Monitoring', 'All access to sensitive data must be logged and monitored for suspicious activity.', 'HIGH','APPROVED', 'Monitoring enables early detection of unauthorized access attempts.', 'ISO/IEC 25010 – Confidentiality', 'Unauthorized access may go undetected, increasing breach impact.'),
    ((select id from category_sub where short_name='CON'), 'SEC-CON-10', 'Data Masking in User Interfaces', 'Sensitive data displayed in the UI must be masked unless explicitly required and authorized.', 'HIGH','APPROVED', 'Masking prevents shoulder-surfing and accidental exposure.', 'ISO/IEC 25010 – Confidentiality', 'Visible sensitive data may be exposed to unauthorized viewers.');
INSERT INTO requirements
    (category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='ING'), 'SEC-ING-01', 'Prevent Unauthorized Data Modification', 'The system shall ensure that only authenticated and authorized users can modify stored or transmitted data.', 'HIGH', 'APPROVED', 'Integrity requires that data is modified only by legitimate actors.', 'ISO/IEC 25010 – Security: Integrity', 'Unauthorized changes may corrupt critical business data and compromise decision-making.'),
    ((select id from category_sub where short_name='ING'), 'SEC-ING-02', 'Ensure Transaction Atomicity', 'The system shall ensure that all multi-step transactions are completed fully or rolled back to a consistent state.', 'HIGH', 'APPROVED', 'Atomicity prevents partial updates that can lead to inconsistent data.', 'ISO/IEC 25010 – Security: Integrity', 'Partial writes may result in inconsistent or corrupted records.'),
    ((select id from category_sub where short_name='ING'), 'SEC-ING-03', 'Protect Data Against Tampering in Transit', 'The system shall use cryptographic mechanisms to prevent unauthorized modification of data during transmission.', 'HIGH', 'APPROVED', 'Integrity must be preserved across communication channels.', 'ISO/IEC 25010 – Security: Integrity', 'Attackers may alter data packets, leading to fraud or system compromise.'),
    ((select id from category_sub where short_name='ING'), 'SEC-ING-04', 'Implement Input Validation Controls', 'The system shall validate all external inputs to prevent injection, corruption, or manipulation of stored data.', 'HIGH', 'APPROVED', 'Input validation is a foundational control for maintaining data integrity.', 'OWASP ASVS / ISO/IEC 25010', 'Invalid or malicious input may corrupt data or enable unauthorized modification.'),
    ((select id from category_sub where short_name='ING'), 'SEC-ING-05', 'Maintain Immutable Audit Logs', 'The system shall maintain tamper-evident audit logs for all data modification events.', 'HIGH', 'APPROVED', 'Auditability supports detection of unauthorized or accidental changes.', 'ISO/IEC 27001 A.12.4 / ISO/IEC 25010', 'Tampered logs may hide malicious activity and hinder forensic analysis.'),
    ((select id from category_sub where short_name='ING'), 'SEC-ING-06', 'Enforce Referential Integrity', 'The system shall enforce referential integrity rules to prevent orphaned, inconsistent, or invalid data relationships.', 'HIGH', 'APPROVED', 'Referential integrity ensures consistent and reliable data structures.', 'ISO/IEC 25010 – Quality Model', 'Broken relationships may cause data loss, inaccurate reporting, or system errors.'),
    ((select id from category_sub where short_name='ING'), 'SEC-ING-07', 'Detect and Reject Duplicate Transactions', 'The system shall detect and prevent duplicate submissions of critical transactions.', 'HIGH', 'APPROVED', 'Duplicate transactions can cause financial or operational inconsistencies.', 'ISO/IEC 25010 – Security: Integrity', 'Duplicate processing may result in double charges, duplicated records, or inconsistent states.'),
    ((select id from category_sub where short_name='ING'), 'SEC-ING-08', 'Ensure Configuration Integrity', 'The system shall protect configuration files and settings from unauthorized modification.', 'HIGH', 'APPROVED', 'Configuration integrity is essential for predictable and secure system behavior.', 'ISO/IEC 27001 A.9 & A.12 / ISO/IEC 25010', 'Altered configurations may introduce vulnerabilities or system instability.'),
    ((select id from category_sub where short_name='ING'), 'SEC-ING-09', 'Implement Data Checksums or Hashing', 'The system shall use checksums or cryptographic hashes to detect unauthorized data modification.', 'HIGH', 'APPROVED', 'Hashing provides a reliable mechanism to detect tampering.', 'NIST SP 800-57 / ISO/IEC 25010', 'Undetected data corruption may propagate errors across dependent systems.'),
    ((select id from category_sub where short_name='ING'), 'SEC-ING-10', 'Prevent Concurrent Update Conflicts', 'The system shall implement concurrency controls to prevent conflicting simultaneous updates to the same data.', 'HIGH', 'APPROVED', 'Concurrency control ensures consistent results in multi-user environments.', 'ISO/IEC 25010 – Security: Integrity', 'Race conditions may cause lost updates, inconsistent states, or corrupted data.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
	((select id from category_sub where short_name='NRP'), 'SEC-NRP-01', 'Record Authenticated User Identity for All Critical Actions', 'The system shall record the authenticated identity of the user performing any critical or irreversible action.', 'HIGH', 'APPROVED', 'Non-repudiation requires binding actions to verified identities.', 'ISO/IEC 25010 – Security: Non-repudiation', 'Users may deny responsibility for harmful or unauthorized actions.'),
    ((select id from category_sub where short_name='NRP'), 'SEC-NRP-02', 'Digitally Sign High-Value Transactions', 'The system shall apply digital signatures or equivalent cryptographic mechanisms to high-value or high-risk transactions.', 'HIGH', 'APPROVED', 'Digital signatures provide strong evidence of origin and integrity.', 'ISO/IEC 27001 A.10 / ISO/IEC 25010', 'Transaction origin cannot be proven, enabling repudiation or fraud.'),
    ((select id from category_sub where short_name='NRP'), 'SEC-NRP-03', 'Maintain Immutable Audit Trails', 'The system shall maintain tamper-evident audit logs for all critical user actions.', 'HIGH', 'APPROVED', 'Immutable logs ensure actions cannot be erased or altered.', 'ISO/IEC 27001 A.12.4 / ISO/IEC 25010', 'Users may deny actions or hide malicious behavior by altering logs.'),
    ((select id from category_sub where short_name='NRP'), 'SEC-NRP-04', 'Timestamp All Critical Events with Trusted Time Source', 'The system shall apply accurate, tamper-resistant timestamps to all critical events.', 'HIGH', 'APPROVED', 'Trusted timestamps support forensic reconstruction and accountability.', 'ISO/IEC 27001 A.12.4 / ISO/IEC 25010', 'Users may dispute event timing, undermining accountability and legal defensibility.'),
    ((select id from category_sub where short_name='NRP'), 'SEC-NRP-05', 'Ensure Integrity of Evidence Records', 'The system shall protect evidence records (logs, signatures, receipts) from unauthorized modification or deletion.', 'HIGH', 'APPROVED', 'Evidence integrity is essential for proving action origin and authenticity.', 'ISO/IEC 27037 / ISO/IEC 25010', 'Compromised evidence may invalidate investigations or legal claims.'),
    ((select id from category_sub where short_name='NRP'), 'SEC-NRP-06', 'Generate User-Visible Transaction Receipts', 'The system shall generate verifiable receipts for critical user actions and make them accessible to the initiating user.', 'HIGH', 'APPROVED', 'Receipts provide proof of action and prevent denial of submission.', 'ISO/IEC 25010 – Security: Non-repudiation', 'Users may claim they never submitted or approved a transaction.'),
    ((select id from category_sub where short_name='NRP'), 'SEC-NRP-07', 'Bind Actions to Session and Device Identifiers', 'The system shall associate critical actions with session identifiers and device fingerprints where feasible.', 'HIGH', 'APPROVED', 'Additional context strengthens attribution and reduces repudiation risk.', 'ISO/IEC 27001 A.9 / ISO/IEC 25010', 'Users may deny involvement by claiming session hijacking or device misuse.'),
    ((select id from category_sub where short_name='NRP'), 'SEC-NRP-08', 'Require Strong Authentication for High-Risk Actions', 'The system shall require strong or multi-factor authentication before performing high-risk or irreversible actions.', 'HIGH', 'APPROVED', 'Strong authentication ensures actions are attributable to legitimate users.', 'ISO/IEC 27001 A.9.4 / ISO/IEC 25010', 'Users may deny responsibility by claiming unauthorized access.'),
    ((select id from category_sub where short_name='NRP'), 'SEC-NRP-09', 'Retain Non-Repudiation Evidence for Compliance Period', 'The system shall retain all non-repudiation evidence for the duration required by legal, regulatory, or business policies.', 'HIGH', 'APPROVED', 'Retention ensures evidence is available when disputes arise.', 'ISO/IEC 27001 A.18 / ISO/IEC 25010', 'Lack of evidence may invalidate audits, investigations, or legal claims.'),
    ((select id from category_sub where short_name='NRP'), 'SEC-NRP-10', 'Ensure Non-Repudiation for System-to-System Communications', 'The system shall implement mechanisms such as mutual authentication and message signing to ensure non-repudiation between integrated systems.', 'HIGH', 'APPROVED', 'System-level non-repudiation prevents disputes between interconnected services.', 'ISO/IEC 27033 / ISO/IEC 25010', 'Systems may deny sending or receiving critical messages, causing operational or legal conflicts.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='ACT'), 'SEC-ACT-01', 'Log All User-Initiated Critical Actions', 'The system shall log all user-initiated critical actions, including the user identity, action type, and outcome.', 'HIGH', 'APPROVED', 'Accountability requires traceability of user actions.', 'ISO/IEC 25010 – Security: Accountability', 'Lack of traceability prevents identifying responsible parties during incidents.'),
    ((select id from category_sub where short_name='ACT'), 'SEC-ACT-02', 'Record Administrative Configuration Changes', 'The system shall record all administrative configuration changes, including before-and-after values.', 'HIGH', 'APPROVED', 'Administrative actions must be attributable to ensure responsible system management.', 'ISO/IEC 27001 A.12.4 / ISO/IEC 25010', 'Unauthorized or incorrect configuration changes may go undetected.'),
    ((select id from category_sub where short_name='ACT'), 'SEC-ACT-03', 'Associate Actions with Authenticated Sessions', 'The system shall associate all user actions with a unique authenticated session identifier.', 'HIGH', 'APPROVED', 'Session-level attribution strengthens accountability and forensic accuracy.', 'ISO/IEC 25010 – Security: Accountability', 'Actions may be misattributed or untraceable during investigations.'),
    ((select id from category_sub where short_name='ACT'), 'SEC-ACT-04', 'Capture Failed Access Attempts', 'The system shall log all failed authentication and authorization attempts, including source information.', 'HIGH', 'APPROVED', 'Failed attempts provide early indicators of misuse or attack.', 'ISO/IEC 27001 A.12.4 / ISO/IEC 25010', 'Potential attacks may go unnoticed, reducing accountability and detection capability.'),
    ((select id from category_sub where short_name='ACT'), 'SEC-ACT-05', 'Ensure Audit Log Integrity Protections', 'The system shall protect audit logs from unauthorized modification or deletion.', 'HIGH', 'APPROVED', 'Integrity of logs is essential for reliable accountability.', 'ISO/IEC 27001 A.12.4 / ISO/IEC 25010', 'Tampered logs may hide malicious activity or prevent attribution.'),
    ((select id from category_sub where short_name='ACT'), 'SEC-ACT-06', 'Log System-to-System Interactions', 'The system shall log all system-to-system interactions, including service identity and action details.', 'HIGH', 'APPROVED', 'Accountability extends to automated and service-level interactions.', 'ISO/IEC 27033 / ISO/IEC 25010', 'Failures or malicious actions by integrated systems may be untraceable.'),
    ((select id from category_sub where short_name='ACT'), 'SEC-ACT-07', 'Provide Role-Based Audit Log Access', 'The system shall restrict access to audit logs based on role and need-to-know principles.', 'HIGH', 'APPROVED', 'Limiting access prevents tampering and protects sensitive accountability data.', 'ISO/IEC 27001 A.9 / ISO/IEC 25010', 'Unauthorized access may lead to log manipulation or privacy violations.'),
    ((select id from category_sub where short_name='ACT'), 'SEC-ACT-08', 'Record Automated System Actions', 'The system shall log automated system actions that affect data, configuration, or security posture.', 'HIGH', 'APPROVED', 'Automated processes must be accountable to support traceability and diagnostics.', 'ISO/IEC 25010 – Security: Accountability', 'Automated changes may be misinterpreted as user actions or remain unexplained.'),
    ((select id from category_sub where short_name='ACT'), 'SEC-ACT-09', 'Ensure Audit Logs Capture Sufficient Detail', 'The system shall ensure audit logs contain sufficient detail to identify who performed an action, what was done, when it occurred, and the outcome.', 'HIGH', 'APPROVED', 'Detailed logs enable accurate reconstruction of events.', 'ISO/IEC 27001 A.12.4 / ISO/IEC 25010', 'Insufficient detail may prevent determining responsibility during incidents.'),
    ((select id from category_sub where short_name='ACT'), 'SEC-ACT-10', 'Retain Accountability Records for Required Duration', 'The system shall retain accountability-related logs and evidence for the duration required by policy, regulation, or business need.', 'HIGH', 'APPROVED', 'Retention ensures accountability information is available for audits and investigations.', 'ISO/IEC 27001 A.18 / ISO/IEC 25010', 'Premature deletion may hinder compliance, audits, or forensic analysis.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='AUT'), 'SEC-AUT-01', 'Verify Authenticity of All Users Before Access', 'The system shall verify the authenticity of all users through secure authentication mechanisms before granting access to protected resources.', 'HIGH', 'APPROVED', 'Authenticity ensures that only legitimate users access the system.', 'ISO/IEC 25010 – Security: Authenticity', 'Unauthorized users may impersonate legitimate users and gain access to sensitive data.'),
    ((select id from category_sub where short_name='AUT'), 'SEC-AUT-02', 'Authenticate All System-to-System Communications', 'The system shall authenticate all external systems and services before exchanging data.', 'HIGH', 'APPROVED', 'Authenticating systems prevents spoofing and unauthorized integrations.', 'ISO/IEC 27033 / ISO/IEC 25010', 'Malicious systems may impersonate trusted services and inject harmful data.'),
    ((select id from category_sub where short_name='AUT'), 'SEC-AUT-03', 'Use Strong Credential Protection Mechanisms', 'The system shall store and manage authentication credentials using secure, industry-standard protection mechanisms.', 'HIGH', 'APPROVED', 'Credential protection is essential to prevent impersonation.', 'NIST SP 800-63 / ISO/IEC 25010', 'Compromised credentials allow attackers to impersonate legitimate users.'),
    ((select id from category_sub where short_name='AUT'), 'SEC-AUT-04', 'Validate Authenticity of Incoming Data', 'The system shall validate the authenticity of incoming data using signatures, tokens, or trusted metadata.', 'HIGH', 'APPROVED', 'Authenticity validation prevents data spoofing and tampering.', 'ISO/IEC 27001 A.14 / ISO/IEC 25010', 'Spoofed or manipulated data may be processed as legitimate.'),
    ((select id from category_sub where short_name='AUT'), 'SEC-AUT-05', 'Enforce Multi-Factor Authentication for Sensitive Actions', 'The system shall require multi-factor authentication for sensitive or high-risk operations.', 'HIGH', 'APPROVED', 'MFA strengthens authenticity by requiring multiple proofs of identity.', 'NIST SP 800-63 / ISO/IEC 25010', 'Attackers may impersonate users with only a single compromised factor.'),
    ((select id from category_sub where short_name='AUT'), 'SEC-AUT-06', 'Authenticate Devices Before Granting Access', 'The system shall authenticate devices using certificates, tokens, or hardware identifiers before allowing access.', 'HIGH', 'APPROVED', 'Device authentication prevents unauthorized or rogue devices from connecting.', 'ISO/IEC 27033 / ISO/IEC 25010', 'Untrusted devices may impersonate legitimate endpoints and compromise the system.'),
    ((select id from category_sub where short_name='AUT'), 'SEC-AUT-07', 'Ensure Authenticity of Software Components', 'The system shall verify the authenticity of software components, libraries, and updates before installation or execution.', 'HIGH', 'APPROVED', 'Authenticity checks prevent supply-chain attacks.', 'ISO/IEC 27034 / ISO/IEC 25010', 'Malicious or tampered components may be installed as trusted software.'),
    ((select id from category_sub where short_name='AUT'), 'SEC-AUT-08', 'Authenticate API Clients', 'The system shall authenticate all API clients using secure tokens, certificates, or signed requests.', 'HIGH', 'APPROVED', 'API authentication ensures only trusted clients can invoke system functions.', 'OWASP API Security / ISO/IEC 25010', 'Unauthenticated clients may impersonate trusted applications and misuse APIs.'),
    ((select id from category_sub where short_name='AUT'), 'SEC-AUT-09', 'Verify Authenticity of User Sessions', 'The system shall validate the authenticity of user sessions using secure session tokens resistant to prediction and tampering.', 'HIGH', 'APPROVED', 'Session authenticity prevents hijacking and impersonation.', 'OWASP ASVS / ISO/IEC 25010', 'Attackers may hijack or forge sessions to impersonate users.'),
    ((select id from category_sub where short_name='AUT'), 'SEC-AUT-10', 'Authenticate Data Sources in Distributed Systems', 'The system shall authenticate all data sources in distributed or message-driven architectures before processing their messages.', 'HIGH', 'APPROVED', 'Authenticity ensures that messages originate from trusted producers.', 'ISO/IEC 27033 / ISO/IEC 25010', 'Unverified sources may inject malicious or misleading data into the system.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='RES'), 'SEC-RES-01', 'Resist Brute-Force Authentication Attempts', 'The system shall detect and block brute-force authentication attempts through rate limiting, lockouts, or adaptive controls.', 'HIGH', 'APPROVED', 'Resistance mechanisms reduce the likelihood of credential compromise.', 'ISO/IEC 25010 – Security: Resistance', 'Attackers may gain unauthorized access through repeated automated attempts.'),
    ((select id from category_sub where short_name='RES'), 'SEC-RES-02', 'Resist Denial-of-Service Attacks', 'The system shall implement controls to detect and mitigate denial-of-service attacks, ensuring continued availability.', 'HIGH', 'APPROVED', 'DoS resistance ensures the system remains operational under hostile conditions.', 'ISO/IEC 27033 / ISO/IEC 25010', 'Critical services may become unavailable, disrupting business operations.'),
    ((select id from category_sub where short_name='RES'), 'SEC-RES-03', 'Resist Injection Attacks', 'The system shall validate and sanitize all inputs to resist injection attacks such as SQL, command, or LDAP injection.', 'HIGH', 'APPROVED', 'Input validation is essential to withstand malicious payloads.', 'OWASP ASVS / ISO/IEC 25010', 'Attackers may manipulate system behavior or access sensitive data.'),
    ((select id from category_sub where short_name='RES'), 'SEC-RES-04', 'Resist Cross-Site Scripting (XSS) Attacks', 'The system shall implement output encoding and content security controls to resist XSS attacks.', 'HIGH', 'APPROVED', 'XSS resistance prevents unauthorized script execution in user contexts.', 'OWASP ASVS / ISO/IEC 25010', 'Attackers may hijack sessions, steal data, or manipulate user actions.'),
    ((select id from category_sub where short_name='RES'), 'SEC-RES-05', 'Resist Unauthorized Elevation of Privilege', 'The system shall enforce strict privilege boundaries to resist attempts to escalate user privileges.', 'HIGH', 'APPROVED', 'Privilege separation is essential to limit attacker impact.', 'ISO/IEC 27001 A.9 / ISO/IEC 25010', 'Attackers may gain administrative control and compromise the entire system.'),
    ((select id from category_sub where short_name='RES'), 'SEC-RES-06', 'Resist Replay Attacks', 'The system shall use nonces, timestamps, or sequence validation to resist replay of previously valid messages.', 'HIGH', 'APPROVED', 'Replay protection ensures actions cannot be fraudulently repeated.', 'ISO/IEC 27033 / ISO/IEC 25010', 'Attackers may reuse intercepted messages to perform unauthorized actions.'),
    ((select id from category_sub where short_name='RES'), 'SEC-RES-07', 'Resist Malware and Malicious Code Execution', 'The system shall prevent execution of unauthorized or untrusted code through sandboxing, validation, or signature checks.', 'HIGH', 'APPROVED', 'Preventing malicious code execution strengthens system resilience.', 'ISO/IEC 27001 A.12 / ISO/IEC 25010', 'Malware may compromise data, functionality, or system integrity.'),
    ((select id from category_sub where short_name='RES'), 'SEC-RES-08', 'Resist Network-Based Attacks', 'The system shall implement firewalls, intrusion detection, and secure protocols to resist network-based attacks.', 'HIGH', 'APPROVED', 'Network hardening reduces exposure to external threats.', 'ISO/IEC 27033 / ISO/IEC 25010', 'Attackers may exploit open ports or weak protocols to infiltrate the system.'),
    ((select id from category_sub where short_name='RES'), 'SEC-RES-09', 'Resist Data Tampering Attempts', 'The system shall detect and prevent unauthorized attempts to alter stored or transmitted data.', 'HIGH', 'APPROVED', 'Resistance to tampering preserves data integrity and trust.', 'ISO/IEC 25010 – Security: Resistance', 'Attackers may corrupt or manipulate data, leading to operational failures.'),
    ((select id from category_sub where short_name='RES'), 'SEC-RES-10', 'Resist Automated Attack Tools', 'The system shall detect and mitigate automated scanning, enumeration, and exploitation attempts.', 'HIGH', 'APPROVED', 'Automated tools accelerate attacker capabilities; resistance reduces exposure.', 'OWASP ASVS / ISO/IEC 25010', 'Attackers may rapidly discover and exploit vulnerabilities at scale.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='MOD'), 'MAI-MOD-01', 'Module Boundary Definition', 'The system shall define clear and explicit module boundaries to ensure each module has a well-scoped responsibility.', 'HIGH','APPROVED', 'Clear boundaries reduce coupling and improve maintainability.', 'ISO 25010 – Maintainability: Modularity', 'Poorly defined boundaries lead to tangled dependencies and high maintenance cost.'),
    ((select id from category_sub where short_name='MOD'), 'MAI-MOD-02', 'Low Coupling Between Modules', 'The system shall ensure modules interact through minimal and well-defined interfaces to maintain low coupling.', 'HIGH','APPROVED', 'Low coupling reduces the impact of changes and improves testability.', 'ISO 25010 – Maintainability: Modularity', 'High coupling causes cascading failures and expensive refactoring.'),
    ((select id from category_sub where short_name='MOD'), 'MAI-MOD-03', 'High Cohesion Within Modules', 'Each module shall contain functionality that is strongly related and focused on a single purpose.', 'HIGH','APPROVED', 'High cohesion improves readability and reduces complexity.', 'ISO 25010 – Maintainability: Modularity', 'Low cohesion results in bloated modules that are difficult to maintain.'),
    ((select id from category_sub where short_name='MOD'), 'MAI-MOD-04', 'Stable Module Interfaces', 'Module interfaces shall remain stable and backward compatible unless a controlled versioning process is followed.', 'HIGH','APPROVED', 'Stable interfaces reduce integration issues and maintenance overhead.', 'ISO 25010 – Maintainability: Modularity', 'Unstable interfaces break dependent modules and increase regression risk.'),
    ((select id from category_sub where short_name='MOD'), 'MAI-MOD-05', 'Encapsulation of Internal Logic', 'Modules shall encapsulate internal logic and expose only necessary public operations.', 'HIGH','APPROVED', 'Encapsulation prevents unintended dependencies and supports modular evolution.', 'ISO 25010 – Maintainability: Modularity', 'Exposed internals lead to tight coupling and fragile code.'),
    ((select id from category_sub where short_name='MOD'), 'MAI-MOD-06', 'Independent Deployability of Modules', 'Modules shall be designed to allow independent deployment without requiring full system redeployment.', 'HIGH','APPROVED', 'Independent deployability accelerates updates and reduces downtime.', 'ISO 25010 – Maintainability: Modularity', 'Tightly coupled deployment pipelines slow releases and increase operational risk.'),
    ((select id from category_sub where short_name='MOD'), 'MAI-MOD-07', 'Module-Level Testability', 'Each module shall support isolated unit and integration testing without requiring unrelated modules.', 'HIGH','APPROVED', 'Testable modules reduce defect rates and improve maintainability.', 'ISO 25010 – Maintainability: Modularity', 'Untestable modules hide defects and increase maintenance effort.'),
    ((select id from category_sub where short_name='MOD'), 'MAI-MOD-08', 'Clear Module Dependency Rules', 'The system shall define and enforce rules for allowable module dependencies (e.g., layered architecture constraints).', 'HIGH','APPROVED', 'Dependency rules prevent architectural erosion over time.', 'ISO 25010 – Maintainability: Modularity', 'Uncontrolled dependencies create spaghetti architecture and slow development.'),
    ((select id from category_sub where short_name='MOD'), 'MAI-MOD-09', 'Module Reusability', 'Modules shall be designed for reuse across different system components or projects where applicable.', 'HIGH','APPROVED', 'Reusability reduces duplication and long-term maintenance cost.', 'ISO 25010 – Maintainability: Modularity', 'Lack of reusability leads to redundant code and inconsistent behavior.'),
    ((select id from category_sub where short_name='MOD'), 'MAI-MOD-10', 'Module Size Constraints', 'Modules shall be kept within reasonable size limits to avoid excessive complexity and ensure maintainability.', 'HIGH','APPROVED', 'Smaller modules are easier to understand, test, and modify.', 'ISO 25010 – Maintainability: Modularity', 'Oversized modules become difficult to maintain and prone to defects.'),
    ((select id from category_sub where short_name='MOD'), 'MAI-MOD-11', 'Versioning of Modules', 'Modules shall follow a structured versioning scheme to track changes and maintain compatibility.', 'HIGH','APPROVED', 'Versioning supports controlled evolution and reduces integration risk.', 'ISO 25010 – Maintainability: Modularity', 'Lack of versioning causes confusion, incompatibilities, and deployment failures.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='REU'), 'MAI-REU-01', 'Reusable Component Design', 'The system shall design components to be reusable across multiple modules or projects without modification.', 'HIGH','APPROVED', 'Reusable components reduce duplication and long-term maintenance effort.', 'ISO 25010 – Maintainability: Reusability', 'Failure to design reusable components leads to redundant code and inconsistent behavior.'),
    ((select id from category_sub where short_name='REU'), 'MAI-REU-02', 'Generalized Interfaces', 'Components shall expose generalized and parameterized interfaces to support reuse in varying contexts.', 'HIGH','APPROVED', 'Generalized interfaces increase adaptability and reduce the need for custom implementations.', 'ISO 25010 – Maintainability: Reusability', 'Overly specific interfaces limit reuse and increase development time.'),
    ((select id from category_sub where short_name='REU'), 'MAI-REU-03', 'Documentation for Reusable Components', 'All reusable components shall include clear documentation describing usage, constraints, and integration steps.', 'HIGH','APPROVED', 'Documentation enables consistent reuse and reduces onboarding time.', 'ISO 25010 – Maintainability: Reusability', 'Poor documentation discourages reuse and increases support burden.'),
    ((select id from category_sub where short_name='REU'), 'MAI-REU-04', 'Decoupled Component Dependencies', 'Reusable components shall minimize dependencies on specific system modules or technologies.', 'HIGH','APPROVED', 'Decoupling increases portability and reuse across environments.', 'ISO 25010 – Maintainability: Reusability', 'Tight dependencies restrict reuse and cause integration failures.'),
    ((select id from category_sub where short_name='REU'), 'MAI-REU-05', 'Configurable Component Behavior', 'Reusable components shall support configuration options to adapt behavior without code changes.', 'HIGH','APPROVED', 'Configurability increases flexibility and reduces the need for component duplication.', 'ISO 25010 – Maintainability: Reusability', 'Hard-coded behavior forces developers to fork or rewrite components.'),
    ((select id from category_sub where short_name='REU'), 'MAI-REU-06', 'Standardized Coding Practices for Reuse', 'The system shall follow standardized coding conventions to ensure components are predictable and reusable.', 'HIGH','APPROVED', 'Consistency improves readability and reuse potential.', 'ISO 25010 – Maintainability: Reusability', 'Inconsistent coding practices reduce trust and discourage reuse.'),
    ((select id from category_sub where short_name='REU'), 'MAI-REU-07', 'Reusable Error Handling Patterns', 'Reusable components shall implement standardized error handling patterns to ensure predictable behavior.', 'HIGH','APPROVED', 'Consistent error handling improves reliability and integration success.', 'ISO 25010 – Maintainability: Reusability', 'Inconsistent error handling causes unexpected failures and reduces component adoption.'),
    ((select id from category_sub where short_name='REU'), 'MAI-REU-08', 'Backward Compatibility of Reusable Components', 'Updates to reusable components shall maintain backward compatibility or provide clear migration paths.', 'HIGH','APPROVED', 'Backward compatibility protects dependent systems and encourages reuse.', 'ISO 25010 – Maintainability: Reusability', 'Breaking changes disrupt multiple systems and increase maintenance workload.'),
    ((select id from category_sub where short_name='REU'), 'MAI-REU-09', 'Reusable Component Testing', 'Reusable components shall include automated tests validating their behavior in isolation.', 'HIGH','APPROVED', 'Testing ensures reliability and confidence in reuse.', 'ISO 25010 – Maintainability: Reusability', 'Untested components introduce defects across all systems that reuse them.'),
    ((select id from category_sub where short_name='REU'), 'MAI-REU-10', 'Repository for Reusable Assets', 'The organization shall maintain a centralized repository for reusable components, templates, and libraries.', 'HIGH','APPROVED', 'A shared repository increases discoverability and adoption of reusable assets.', 'ISO 25010 – Maintainability: Reusability', 'Lack of a repository leads to duplicated effort and inconsistent implementations.'),
    ((select id from category_sub where short_name='REU'), 'MAI-REU-11', 'Reuse Evaluation During Design', 'Design reviews shall include an assessment of opportunities to reuse existing components before creating new ones.', 'HIGH','APPROVED', 'Proactive evaluation reduces unnecessary development and promotes architectural consistency.', 'ISO 25010 – Maintainability: Reusability', 'Missed reuse opportunities increase cost, complexity, and codebase fragmentation.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='ANZ'), 'MAI-ANZ-01', 'Root Cause Identification Support', 'The system shall provide mechanisms such as logs, traces, or diagnostics to support rapid identification of root causes for failures.', 'HIGH','APPROVED', 'Effective diagnostics reduce time to analyze and resolve issues.', 'ISO 25010 – Maintainability: Analyzability', 'Insufficient diagnostics lead to prolonged outages and costly troubleshooting.'),
    ((select id from category_sub where short_name='ANZ'), 'MAI-ANZ-02', 'Readable and Understandable Code Structure', 'The codebase shall follow consistent naming, formatting, and structural conventions to improve understandability.', 'HIGH','APPROVED', 'Readable code accelerates analysis and reduces onboarding time.', 'ISO 25010 – Maintainability: Analyzability', 'Poor readability increases analysis time and error likelihood during maintenance.'),
    ((select id from category_sub where short_name='ANZ'), 'MAI-ANZ-03', 'Traceability from Requirements to Code', 'The system shall maintain traceability links between requirements, design elements, and code modules.', 'HIGH','APPROVED', 'Traceability enables efficient impact analysis and defect isolation.', 'ISO 25010 – Maintainability: Analyzability', 'Lack of traceability leads to incorrect assumptions and unintended side effects during changes.'),
    ((select id from category_sub where short_name='ANZ'), 'MAI-ANZ-04', 'Error and Exception Transparency', 'The system shall provide clear and descriptive error messages that support rapid analysis of failures.', 'HIGH','APPROVED', 'Clear errors reduce diagnostic time and improve maintainability.', 'ISO 25010 – Maintainability: Analyzability', 'Vague or missing error messages slow down troubleshooting and increase downtime.'),
    ((select id from category_sub where short_name='ANZ'), 'MAI-ANZ-05', 'Availability of Architectural Documentation', 'The system shall include up-to-date architectural documentation to support analysis of system behavior and dependencies.', 'HIGH','APPROVED', 'Documentation accelerates understanding and reduces analysis errors.', 'ISO 25010 – Maintainability: Analyzability', 'Outdated or missing documentation leads to incorrect assumptions and costly mistakes.'),
    ((select id from category_sub where short_name='ANZ'), 'MAI-ANZ-06', 'Static Analysis Compliance', 'The system shall comply with static analysis rules that detect defects, code smells, and maintainability issues.', 'HIGH','APPROVED', 'Static analysis improves analyzability by identifying issues early.', 'ISO 25010 – Maintainability: Analyzability', 'Ignoring static analysis results leads to hidden defects and harder analysis later.'),
    ((select id from category_sub where short_name='ANZ'), 'MAI-ANZ-07', 'Logging Coverage Requirements', 'Critical system operations shall include structured logging to support analysis of runtime behavior.', 'HIGH','APPROVED', 'Logging provides essential insight into system state and execution flow.', 'ISO 25010 – Maintainability: Analyzability', 'Insufficient logging makes it difficult to diagnose issues and verify system behavior.'),
    ((select id from category_sub where short_name='ANZ'), 'MAI-ANZ-08', 'Dependency Mapping Availability', 'The system shall maintain an up-to-date map of module and service dependencies to support impact analysis.', 'HIGH','APPROVED', 'Dependency visibility reduces risk during change analysis.', 'ISO 25010 – Maintainability: Analyzability', 'Unknown dependencies cause unexpected failures and regression defects.'),
    ((select id from category_sub where short_name='ANZ'), 'MAI-ANZ-09', 'Test Coverage for Critical Components', 'Critical components shall maintain automated test coverage sufficient to support analysis of failures and behavior.', 'HIGH','APPROVED', 'Tests provide insight into expected behavior and support defect analysis.', 'ISO 25010 – Maintainability: Analyzability', 'Low test coverage increases uncertainty and slows down root cause analysis.'),
    ((select id from category_sub where short_name='ANZ'), 'MAI-ANZ-10', 'Monitoring and Metrics Availability', 'The system shall expose operational metrics to support analysis of performance, stability, and anomalies.', 'HIGH','APPROVED', 'Metrics provide early indicators of issues and support rapid analysis.', 'ISO 25010 – Maintainability: Analyzability', 'Missing metrics delay detection of issues and hinder root cause identification.'),
    ((select id from category_sub where short_name='ANZ'), 'MAI-ANZ-11', 'Consistent Use of Design Patterns', 'The system shall apply design patterns consistently to improve predictability and ease of analysis.', 'HIGH','APPROVED', 'Predictable structure accelerates comprehension and analysis.', 'ISO 25010 – Maintainability: Analyzability', 'Inconsistent design approaches increase cognitive load and analysis time.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='MDF'), 'MAI-MDF-01', 'Impact Isolation for Changes', 'The system shall be designed so that modifications to one component do not require changes to unrelated components.', 'HIGH','APPROVED', 'Isolating change reduces regression risk and accelerates maintenance.', 'ISO 25010 – Maintainability: Modifiability', 'Changes may cascade across components, increasing cost and defect likelihood.'),
    ((select id from category_sub where short_name='MDF'), 'MAI-MDF-02', 'Clear Change Propagation Rules', 'The system shall define rules for how changes propagate through modules, interfaces, and data structures.', 'HIGH','APPROVED', 'Defined propagation rules reduce uncertainty and improve modification planning.', 'ISO 25010 – Maintainability: Modifiability', 'Uncontrolled propagation leads to unpredictable behavior and system instability.'),
    ((select id from category_sub where short_name='MDF'), 'MAI-MDF-03', 'Modifiable Configuration Settings', 'The system shall externalize configuration values to allow modification without code changes.', 'HIGH','APPROVED', 'Externalized configuration reduces deployment risk and accelerates updates.', 'ISO 25010 – Maintainability: Modifiability', 'Hard-coded values require code changes for simple adjustments, increasing risk and effort.'),
    ((select id from category_sub where short_name='MDF'), 'MAI-MDF-04', 'Stable and Versioned APIs', 'APIs shall be versioned and designed to support modification without breaking existing consumers.', 'HIGH','APPROVED', 'Versioning enables safe evolution of system interfaces.', 'ISO 25010 – Maintainability: Modifiability', 'Unversioned APIs cause breaking changes and widespread integration failures.'),
    ((select id from category_sub where short_name='MDF'), 'MAI-MDF-05', 'Modifiable Business Rules', 'Business rules shall be implemented in a way that allows modification without requiring structural code changes.', 'HIGH','APPROVED', 'Flexible rule implementation supports rapid adaptation to business needs.', 'ISO 25010 – Maintainability: Modifiability', 'Rigid rule implementation slows response to business changes and increases maintenance cost.'),
    ((select id from category_sub where short_name='MDF'), 'MAI-MDF-06', 'Separation of Concerns', 'The system shall separate concerns across layers and modules to simplify modification of individual behaviors.', 'HIGH','APPROVED', 'Separation of concerns reduces complexity and modification effort.', 'ISO 25010 – Maintainability: Modifiability', 'Tightly mixed concerns make modifications risky and error-prone.'),
    ((select id from category_sub where short_name='MDF'), 'MAI-MDF-07', 'Predictable Modification Effort', 'The system shall be structured so that the effort required to modify a feature is proportional to the scope of the change.', 'HIGH','APPROVED', 'Predictability supports planning and reduces maintenance uncertainty.', 'ISO 25010 – Maintainability: Modifiability', 'Unpredictable modification effort leads to delays and underestimated risks.'),
    ((select id from category_sub where short_name='MDF'), 'MAI-MDF-08', 'Automated Regression Testing Support', 'The system shall include automated tests that validate existing functionality after modifications.', 'HIGH','APPROVED', 'Automated tests reduce the risk of introducing regressions during modifications.', 'ISO 25010 – Maintainability: Modifiability', 'Lack of regression tests increases the likelihood of breaking existing functionality.'),
    ((select id from category_sub where short_name='MDF'), 'MAI-MDF-09', 'Modifiable Data Models', 'Data models shall be designed to support extension or modification with minimal impact on existing functionality.', 'HIGH','APPROVED', 'Flexible data models support evolving business requirements.', 'ISO 25010 – Maintainability: Modifiability', 'Rigid data structures require invasive changes and risk data integrity issues.'),
    ((select id from category_sub where short_name='MDF'), 'MAI-MDF-10', 'Support for Feature Toggle Mechanisms', 'The system shall support feature toggles to enable safe rollout and modification of features.', 'HIGH','APPROVED', 'Feature toggles allow controlled modification and reduce deployment risk.', 'ISO 25010 – Maintainability: Modifiability', 'Without toggles, modifications require risky full deployments and limit rollback options.'),
    ((select id from category_sub where short_name='MDF'), 'MAI-MDF-11', 'Clear Modification Guidelines', 'The system shall include documented guidelines for modifying code, configuration, and interfaces.', 'HIGH','APPROVED', 'Guidelines ensure consistent and safe modifications across teams.', 'ISO 25010 – Maintainability: Modifiability', 'Inconsistent modification practices increase defects and architectural drift.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='TST'), 'MAI-TST-01', 'Support for Isolated Testing', 'The system shall allow components to be tested independently without requiring unrelated modules or external systems.', 'HIGH','APPROVED', 'Isolation reduces test complexity and improves defect localization.', 'ISO 25010 – Maintainability: Testability', 'Tightly coupled components make testing difficult and increase defect propagation.'),
    ((select id from category_sub where short_name='TST'), 'MAI-TST-02', 'Deterministic Component Behavior', 'Components shall behave deterministically under the same inputs to ensure reliable and repeatable tests.', 'HIGH','APPROVED', 'Determinism ensures consistent test results and easier debugging.', 'ISO 25010 – Maintainability: Testability', 'Non-deterministic behavior leads to flaky tests and unreliable defect detection.'),
    ((select id from category_sub where short_name='TST'), 'MAI-TST-03', 'Test Data Management Support', 'The system shall provide mechanisms to create, reset, and manage test data in a controlled manner.', 'HIGH','APPROVED', 'Controlled test data ensures repeatability and reduces test setup time.', 'ISO 25010 – Maintainability: Testability', 'Unmanaged test data leads to inconsistent results and unreliable testing.'),
    ((select id from category_sub where short_name='TST'), 'MAI-TST-04', 'Mocking and Stubbing Capability', 'The system shall support mocking or stubbing of external dependencies to enable isolated testing.', 'HIGH','APPROVED', 'Mocking reduces reliance on external systems and improves test reliability.', 'ISO 25010 – Maintainability: Testability', 'Inability to mock dependencies results in slow, brittle, and environment-dependent tests.'),
    ((select id from category_sub where short_name='TST'), 'MAI-TST-05', 'Clear and Observable Outputs', 'Components shall expose observable outputs or state changes that allow verification of expected behavior.', 'HIGH','APPROVED', 'Observable behavior enables precise validation of functionality.', 'ISO 25010 – Maintainability: Testability', 'Hidden or ambiguous outputs make it difficult to verify correctness.'),
    ((select id from category_sub where short_name='TST'), 'MAI-TST-06', 'Automated Test Execution Support', 'The system shall support automated execution of unit, integration, and regression tests.', 'HIGH','APPROVED', 'Automation increases test coverage and reduces manual effort.', 'ISO 25010 – Maintainability: Testability', 'Lack of automation leads to slow testing cycles and missed defects.'),
    ((select id from category_sub where short_name='TST'), 'MAI-TST-07', 'Traceable Test Results', 'The system shall provide traceability between test results, test cases, and the components under test.', 'HIGH','APPROVED', 'Traceability supports efficient defect analysis and impact assessment.', 'ISO 25010 – Maintainability: Testability', 'Without traceability, identifying root causes becomes slow and error-prone.'),
    ((select id from category_sub where short_name='TST'), 'MAI-TST-08', 'Support for Test Environment Configuration', 'The system shall allow configuration of test environments to simulate different operational conditions.', 'HIGH','APPROVED', 'Configurable environments improve test completeness and reliability.', 'ISO 25010 – Maintainability: Testability', 'Inflexible environments limit test coverage and hide environment-specific defects.'),
    ((select id from category_sub where short_name='TST'), 'MAI-TST-09', 'Logging for Test Diagnostics', 'The system shall provide detailed and structured logging to support analysis of test failures.', 'HIGH','APPROVED', 'Logging accelerates debugging and improves defect resolution.', 'ISO 25010 – Maintainability: Testability', 'Insufficient logging makes it difficult to diagnose test failures.'),
    ((select id from category_sub where short_name='TST'), 'MAI-TST-10', 'Minimal Side Effects During Testing', 'Components shall minimize side effects to ensure predictable and isolated test execution.', 'HIGH','APPROVED', 'Reducing side effects improves test reliability and simplifies validation.', 'ISO 25010 – Maintainability: Testability', 'Side effects cause inconsistent test results and complicate debugging.'),
    ((select id from category_sub where short_name='TST'), 'MAI-TST-11', 'Support for Code Instrumentation', 'The system shall allow instrumentation (e.g., coverage tools, profilers) without requiring major code changes.', 'HIGH','APPROVED', 'Instrumentation improves visibility into system behavior during testing.', 'ISO 25010 – Maintainability: Testability', 'Inability to instrument code reduces test coverage and hides performance or logic issues.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='ADP'), 'FLX-ADP-01', 'Environment Configuration Adaptability', 'The system shall support configuration changes that allow it to operate in different environments without code modification.', 'HIGH','APPROVED', 'Adaptable configuration reduces deployment effort across environments.', 'ISO 25010 – Flexibility: Adaptability', 'Hard-coded environment settings require code changes and increase deployment risk.'),
    ((select id from category_sub where short_name='ADP'), 'FLX-ADP-02', 'Platform Independence', 'The system shall be designed to operate on multiple platforms or operating systems with minimal adaptation.', 'HIGH','APPROVED', 'Platform independence increases system longevity and deployment flexibility.', 'ISO 25010 – Flexibility: Adaptability', 'Platform-specific dependencies limit deployment options and increase maintenance cost.'),
    ((select id from category_sub where short_name='ADP'), 'FLX-ADP-03', 'Support for Technology Upgrades', 'The system shall be designed to allow upgrading underlying technologies (e.g., libraries, frameworks) with minimal rework.', 'HIGH','APPROVED', 'Technology upgradeability ensures long-term sustainability and security.', 'ISO 25010 – Flexibility: Adaptability', 'Difficult upgrades lead to outdated, insecure, or unsupported technology stacks.'),
    ((select id from category_sub where short_name='ADP'), 'FLX-ADP-04', 'Adaptable Integration Interfaces', 'The system shall provide flexible integration interfaces that can adapt to new external systems or APIs.', 'HIGH','APPROVED', 'Flexible interfaces reduce effort when integrating with evolving external systems.', 'ISO 25010 – Flexibility: Adaptability', 'Rigid interfaces require major redesign when external systems change.'),
    ((select id from category_sub where short_name='ADP'), 'FLX-ADP-05', 'Dynamic Resource Scaling Support', 'The system shall support scaling of resources (e.g., compute, storage) without requiring architectural changes.', 'HIGH','APPROVED', 'Scalability ensures the system can adapt to changing load conditions.', 'ISO 25010 – Flexibility: Adaptability', 'Inability to scale leads to performance degradation and service outages.'),
    ((select id from category_sub where short_name='ADP'), 'FLX-ADP-06', 'Configurable Business Rules', 'The system shall allow business rules to be modified or extended without requiring code-level changes.', 'HIGH','APPROVED', 'Configurable rules support rapid adaptation to evolving business needs.', 'ISO 25010 – Flexibility: Adaptability', 'Hard-coded rules slow response to business changes and increase maintenance cost.'),
    ((select id from category_sub where short_name='ADP'), 'FLX-ADP-07', 'Support for Multiple Deployment Models', 'The system shall support deployment in various models (e.g., on-premise, cloud, hybrid) with minimal adaptation.', 'HIGH','APPROVED', 'Deployment flexibility increases adoption and operational resilience.', 'ISO 25010 – Flexibility: Adaptability', 'Limited deployment options restrict scalability and increase operational constraints.'),
    ((select id from category_sub where short_name='ADP'), 'FLX-ADP-08', 'Adaptable Data Formats', 'The system shall support multiple data formats and allow new formats to be added with minimal effort.', 'HIGH','APPROVED', 'Flexible data handling improves interoperability and future-proofing.', 'ISO 25010 – Flexibility: Adaptability', 'Rigid data formats hinder integration and require costly rework when formats evolve.'),
    ((select id from category_sub where short_name='ADP'), 'FLX-ADP-09', 'Runtime Feature Adaptation', 'The system shall support enabling, disabling, or modifying features at runtime without requiring redeployment.', 'HIGH','APPROVED', 'Runtime adaptability reduces downtime and accelerates feature rollout.', 'ISO 25010 – Flexibility: Adaptability', 'Inability to adapt features at runtime increases operational risk and delays.'),
    ((select id from category_sub where short_name='ADP'), 'FLX-ADP-10', 'Modular Architecture for Adaptation', 'The system shall use a modular architecture that allows components to be replaced or extended independently.', 'HIGH','APPROVED', 'Modularity supports rapid adaptation to new requirements or technologies.', 'ISO 25010 – Flexibility: Adaptability', 'Tightly coupled architecture makes adaptation slow, risky, and expensive.'),
    ((select id from category_sub where short_name='ADP'), 'FLX-ADP-11', 'Support for Localization and Internationalization', 'The system shall support adaptation to different languages, regions, and cultural conventions without code changes.', 'HIGH','APPROVED', 'Localization capability expands usability across markets.', 'ISO 25010 – Flexibility: Adaptability', 'Lack of localization support limits adoption and requires costly retrofitting.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='SCA'), 'FLX-SCA-01', 'Horizontal Scaling Support', 'The system shall support horizontal scaling by adding additional instances or nodes without requiring architectural changes.', 'HIGH','APPROVED', 'Horizontal scaling enables cost-effective capacity increases.', 'ISO 25010 – Flexibility: Scalability', 'Inability to scale horizontally leads to performance bottlenecks and service outages.'),
    ((select id from category_sub where short_name='SCA'), 'FLX-SCA-02', 'Vertical Scaling Capability', 'The system shall support vertical scaling by utilizing increased CPU, memory, or storage resources without reconfiguration.', 'HIGH','APPROVED', 'Vertical scaling allows efficient use of more powerful hardware.', 'ISO 25010 – Flexibility: Scalability', 'Systems that cannot scale vertically may require costly redesigns to handle increased load.'),
    ((select id from category_sub where short_name='SCA'), 'FLX-SCA-03', 'Load Balancing Support', 'The system shall support load balancing mechanisms to distribute workload evenly across instances.', 'HIGH','APPROVED', 'Load balancing improves performance and resilience under high load.', 'ISO 25010 – Flexibility: Scalability', 'Without load balancing, systems become overloaded and prone to failure.'),
    ((select id from category_sub where short_name='SCA'), 'FLX-SCA-04', 'Scalable Data Storage Architecture', 'The system shall support scalable data storage solutions that can grow with increasing data volume.', 'HIGH','APPROVED', 'Scalable storage ensures long-term data availability and performance.', 'ISO 25010 – Flexibility: Scalability', 'Fixed storage limits cause data loss, slowdowns, or costly migrations.'),
    ((select id from category_sub where short_name='SCA'), 'FLX-SCA-05', 'Performance Degradation Thresholds', 'The system shall maintain acceptable performance levels as load increases up to defined scalability thresholds.', 'HIGH','APPROVED', 'Defined thresholds ensure predictable performance under growth.', 'ISO 25010 – Flexibility: Scalability', 'Unpredictable degradation leads to poor user experience and system instability.'),
    ((select id from category_sub where short_name='SCA'), 'FLX-SCA-06', 'Stateless Component Design', 'Components shall be designed to be stateless where possible to support easy replication and scaling.', 'HIGH','APPROVED', 'Stateless design simplifies scaling and reduces synchronization overhead.', 'ISO 25010 – Flexibility: Scalability', 'Stateful components limit scalability and increase failure risk during load spikes.'),
    ((select id from category_sub where short_name='SCA'), 'FLX-SCA-07', 'Scalable Messaging and Queueing', 'The system shall support scalable messaging or queueing mechanisms to handle increased event or request volume.', 'HIGH','APPROVED', 'Scalable messaging prevents bottlenecks in distributed systems.', 'ISO 25010 – Flexibility: Scalability', 'Unscalable queues cause delays, dropped messages, and system failures.'),
    ((select id from category_sub where short_name='SCA'), 'FLX-SCA-08', 'Dynamic Resource Allocation', 'The system shall support dynamic allocation of compute, memory, and network resources based on real-time demand.', 'HIGH','APPROVED', 'Dynamic allocation optimizes resource usage and performance.', 'ISO 25010 – Flexibility: Scalability', 'Static resource allocation leads to overprovisioning or resource exhaustion.'),
    ((select id from category_sub where short_name='SCA'), 'FLX-SCA-09', 'Monitoring for Scalability Metrics', 'The system shall provide monitoring of key scalability metrics such as throughput, latency, and resource utilization.', 'HIGH','APPROVED', 'Monitoring enables proactive scaling and capacity planning.', 'ISO 25010 – Flexibility: Scalability', 'Lack of monitoring results in undetected overload conditions and service degradation.'),
    ((select id from category_sub where short_name='SCA'), 'FLX-SCA-10', 'Support for Distributed Deployment', 'The system shall support distributed deployment across multiple nodes, regions, or data centers.', 'HIGH','APPROVED', 'Distributed deployment improves scalability and resilience.', 'ISO 25010 – Flexibility: Scalability', 'Centralized deployment creates single points of failure and limits scalability.'),
    ((select id from category_sub where short_name='SCA'), 'FLX-SCA-11', 'Graceful Scaling Behavior', 'The system shall scale gracefully under increasing load without sudden performance collapse.', 'HIGH','APPROVED', 'Graceful scaling ensures predictable system behavior during growth.', 'ISO 25010 – Flexibility: Scalability', 'Abrupt performance collapse leads to outages and loss of user trust.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='INS'), 'FLX-INS-01', 'Simplified Installation Process', 'The system shall provide a streamlined installation process requiring minimal manual steps.', 'HIGH','APPROVED', 'A simplified installation reduces deployment time and human error.', 'ISO 25010 – Flexibility: Installability', 'Complex installation increases risk of misconfiguration and failed deployments.'),
    ((select id from category_sub where short_name='INS'), 'FLX-INS-02', 'Automated Installation Scripts', 'The system shall include automated scripts or tools to perform installation tasks consistently.', 'HIGH','APPROVED', 'Automation ensures repeatability and reduces installation variability.', 'ISO 25010 – Flexibility: Installability', 'Manual installation steps lead to inconsistencies and operational delays.'),
    ((select id from category_sub where short_name='INS'), 'FLX-INS-03', 'Pre‑Installation Environment Validation', 'The system shall validate environment prerequisites before installation begins.', 'HIGH','APPROVED', 'Pre‑checks prevent installation failures and reduce troubleshooting time.', 'ISO 25010 – Flexibility: Installability', 'Missing prerequisites cause installation errors and system instability.'),
    ((select id from category_sub where short_name='INS'), 'FLX-INS-04', 'Rollback Capability', 'The system shall support rollback to a previous stable version if installation fails.', 'HIGH','APPROVED', 'Rollback mechanisms reduce downtime and recovery effort.', 'ISO 25010 – Flexibility: Installability', 'Without rollback, failed installations may leave the system in an unusable state.'),
    ((select id from category_sub where short_name='INS'), 'FLX-INS-05', 'Clear Installation Documentation', 'The system shall provide comprehensive installation documentation including steps, prerequisites, and troubleshooting.', 'HIGH','APPROVED', 'Documentation ensures consistent and successful installations.', 'ISO 25010 – Flexibility: Installability', 'Poor documentation leads to installation errors and increased support burden.'),
    ((select id from category_sub where short_name='INS'), 'FLX-INS-06', 'Configurable Installation Parameters', 'The system shall allow configuration of installation parameters such as paths, ports, and environment settings.', 'HIGH','APPROVED', 'Configurable parameters support diverse deployment environments.', 'ISO 25010 – Flexibility: Installability', 'Hard‑coded installation settings limit deployment flexibility and cause conflicts.'),
    ((select id from category_sub where short_name='INS'), 'FLX-INS-07', 'Minimal External Dependencies', 'The system shall minimize external dependencies required during installation.', 'HIGH','APPROVED', 'Reducing dependencies simplifies installation and improves reliability.', 'ISO 25010 – Flexibility: Installability', 'Excessive dependencies increase failure points and complicate deployment.'),
    ((select id from category_sub where short_name='INS'), 'FLX-INS-08', 'Support for Silent Installation', 'The system shall support silent or unattended installation modes.', 'HIGH','APPROVED', 'Silent installation enables automated deployment across multiple systems.', 'ISO 25010 – Flexibility: Installability', 'Lack of silent installation increases manual effort and slows large‑scale deployment.'),
    ((select id from category_sub where short_name='INS'), 'FLX-INS-09', 'Installation Integrity Verification', 'The system shall verify installation integrity using checksums, signatures, or validation routines.', 'HIGH','APPROVED', 'Integrity checks ensure that installation artifacts are complete and unaltered.', 'ISO 25010 – Flexibility: Installability', 'Corrupted or tampered installation files may compromise system stability or security.'),
    ((select id from category_sub where short_name='INS'), 'FLX-INS-10', 'Support for Incremental Installation', 'The system shall support incremental installation or updates without requiring full reinstallation.', 'HIGH','APPROVED', 'Incremental installation reduces downtime and installation effort.', 'ISO 25010 – Flexibility: Installability', 'Requiring full reinstallations increases operational cost and risk.'),
    ((select id from category_sub where short_name='INS'), 'FLX-INS-11', 'Post‑Installation Verification', 'The system shall automatically verify successful installation through health checks or validation tests.', 'HIGH','APPROVED', 'Post‑installation checks ensure the system is operational before use.', 'ISO 25010 – Flexibility: Installability', 'Undetected installation issues may lead to runtime failures and user dissatisfaction.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='REP'), 'FLX-REP-01', 'Component Replacement with Minimal Impact', 'The system shall allow components to be replaced without requiring modifications to unrelated components.', 'HIGH','APPROVED', 'Minimizing impact reduces risk and cost when replacing components.', 'ISO 25010 – Flexibility: Replaceability', 'Tightly coupled components make replacements risky and expensive.'),
    ((select id from category_sub where short_name='REP'), 'FLX-REP-02', 'Standardized Interfaces for Replaceability', 'The system shall use standardized and well-defined interfaces to support replacement of components with alternative implementations.', 'HIGH','APPROVED', 'Standardized interfaces ensure compatibility and simplify replacement.', 'ISO 25010 – Flexibility: Replaceability', 'Non-standard interfaces require extensive rework during replacement.'),
    ((select id from category_sub where short_name='REP'), 'FLX-REP-03', 'Loose Coupling Between Components', 'The system shall maintain loose coupling to ensure components can be replaced independently.', 'HIGH','APPROVED', 'Loose coupling improves flexibility and reduces replacement effort.', 'ISO 25010 – Flexibility: Replaceability', 'Tight coupling forces large-scale changes when replacing a single component.'),
    ((select id from category_sub where short_name='REP'), 'FLX-REP-04', 'Replaceable External Services', 'The system shall allow external services (e.g., APIs, databases) to be replaced with alternatives through configuration or adapters.', 'HIGH','APPROVED', 'Replaceable services reduce vendor lock-in and improve resilience.', 'ISO 25010 – Flexibility: Replaceability', 'Inflexible service integration increases dependency risks and migration costs.'),
    ((select id from category_sub where short_name='REP'), 'FLX-REP-05', 'Clear Replacement Procedures', 'The system shall include documented procedures for replacing components, including steps, dependencies, and validation.', 'HIGH','APPROVED', 'Clear procedures reduce errors and downtime during replacement.', 'ISO 25010 – Flexibility: Replaceability', 'Poor documentation increases replacement time and risk of system failure.'),
    ((select id from category_sub where short_name='REP'), 'FLX-REP-06', 'Backward Compatibility for Replacement', 'The system shall ensure that replacement components maintain backward compatibility or provide migration paths.', 'HIGH','APPROVED', 'Backward compatibility prevents disruptions during component replacement.', 'ISO 25010 – Flexibility: Replaceability', 'Incompatible replacements cause system failures and require major rework.'),
    ((select id from category_sub where short_name='REP'), 'FLX-REP-07', 'Replaceable Configuration Modules', 'The system shall allow configuration modules to be replaced or updated independently of the core application.', 'HIGH','APPROVED', 'Replaceable configuration supports rapid adaptation to new environments.', 'ISO 25010 – Flexibility: Replaceability', 'Static configuration increases deployment complexity and limits adaptability.'),
    ((select id from category_sub where short_name='REP'), 'FLX-REP-08', 'Support for Plug‑and‑Play Components', 'The system shall support plug‑and‑play replacement of components without requiring system downtime.', 'HIGH','APPROVED', 'Plug‑and‑play capability reduces operational disruption.', 'ISO 25010 – Flexibility: Replaceability', 'Replacements requiring downtime reduce availability and increase operational risk.'),
    ((select id from category_sub where short_name='REP'), 'FLX-REP-09', 'Modular Architecture for Replaceability', 'The system shall use a modular architecture that enables individual modules to be replaced independently.', 'HIGH','APPROVED', 'Modularity supports efficient replacement and reduces system-wide impact.', 'ISO 25010 – Flexibility: Replaceability', 'Monolithic architecture makes replacements costly and error-prone.'),
    ((select id from category_sub where short_name='REP'), 'FLX-REP-10', 'Replaceable Data Storage Components', 'The system shall allow data storage components to be replaced or migrated with minimal impact on application logic.', 'HIGH','APPROVED', 'Replaceable storage improves longevity and reduces vendor dependency.', 'ISO 25010 – Flexibility: Replaceability', 'Rigid storage integration complicates migrations and increases long-term risk.'),
    ((select id from category_sub where short_name='REP'), 'FLX-REP-11', 'Validation After Component Replacement', 'The system shall support automated validation to confirm correct behavior after a component is replaced.', 'HIGH','APPROVED', 'Automated validation ensures reliability and reduces post-replacement defects.', 'ISO 25010 – Flexibility: Replaceability', 'Missing validation increases the risk of undetected failures after replacement.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='OPC'), 'SAF-OPC-01', 'Defined Operational Limits', 'The system shall enforce predefined operational limits (e.g., temperature, speed, load) to prevent unsafe conditions.', 'HIGH','APPROVED', 'Operational limits prevent the system from entering hazardous states.', 'ISO 25010 – Safety: Operational Constraint', 'Exceeding safe limits may cause system damage or endanger users.'),
    ((select id from category_sub where short_name='OPC'), 'SAF-OPC-02', 'Safe Mode Activation', 'The system shall automatically enter a safe mode when operational constraints are violated or sensors detect abnormal conditions.', 'HIGH','APPROVED', 'Safe mode reduces risk during abnormal operation.', 'ISO 25010 – Safety: Operational Constraint', 'Failure to enter safe mode may result in hazardous system behavior.'),
    ((select id from category_sub where short_name='OPC'), 'SAF-OPC-03', 'Operational Constraint Monitoring', 'The system shall continuously monitor critical operational parameters and detect deviations from safe ranges.', 'HIGH','APPROVED', 'Continuous monitoring enables early detection of unsafe conditions.', 'ISO 25010 – Safety: Operational Constraint', 'Undetected deviations may escalate into safety incidents.'),
    ((select id from category_sub where short_name='OPC'), 'SAF-OPC-04', 'Fail-Safe Behavior', 'The system shall transition to a fail-safe state when operational constraints cannot be reliably assessed.', 'HIGH','APPROVED', 'Fail-safe behavior minimizes harm when the system is uncertain.', 'ISO 25010 – Safety: Operational Constraint', 'Uncontrolled operation during uncertainty may cause hazardous outcomes.'),
    ((select id from category_sub where short_name='OPC'), 'SAF-OPC-05', 'Constraint Violation Alerts', 'The system shall generate alerts when operational constraints are approached or exceeded.', 'HIGH','APPROVED', 'Alerts enable timely intervention by operators.', 'ISO 25010 – Safety: Operational Constraint', 'Missing alerts may delay corrective action and increase risk.'),
    ((select id from category_sub where short_name='OPC'), 'SAF-OPC-06', 'Redundant Safety Checks', 'The system shall implement redundant safety checks for critical operational constraints.', 'HIGH','APPROVED', 'Redundancy increases reliability of safety mechanisms.', 'ISO 25010 – Safety: Operational Constraint', 'A single point of failure may allow unsafe conditions to go undetected.'),
    ((select id from category_sub where short_name='OPC'), 'SAF-OPC-07', 'Operational Constraint Logging', 'The system shall log all constraint violations and near‑miss events for analysis and safety improvement.', 'HIGH','APPROVED', 'Logging supports root‑cause analysis and continuous safety enhancement.', 'ISO 25010 – Safety: Operational Constraint', 'Lack of logs prevents identification of recurring safety issues.'),
    ((select id from category_sub where short_name='OPC'), 'SAF-OPC-08', 'Environmental Condition Validation', 'The system shall validate environmental conditions (e.g., humidity, pressure, voltage) before and during operation.', 'HIGH','APPROVED', 'Environmental validation ensures safe operation under expected conditions.', 'ISO 25010 – Safety: Operational Constraint', 'Operating in unsuitable environments may cause failures or hazards.'),
    ((select id from category_sub where short_name='OPC'), 'SAF-OPC-09', 'Operator Authorization for Constraint Overrides', 'The system shall restrict overrides of operational constraints to authorized personnel only.', 'HIGH','APPROVED', 'Authorization prevents unsafe manual overrides.', 'ISO 25010 – Safety: Operational Constraint', 'Unauthorized overrides may lead to dangerous system states.'),
    ((select id from category_sub where short_name='OPC'), 'SAF-OPC-10', 'Graceful Degradation Under Constraint Stress', 'The system shall degrade functionality gracefully when approaching operational limits.', 'HIGH','APPROVED', 'Graceful degradation maintains safety while preserving partial functionality.', 'ISO 25010 – Safety: Operational Constraint', 'Abrupt failure under stress may cause unsafe or unpredictable behavior.'),
    ((select id from category_sub where short_name='OPC'), 'SAF-OPC-11', 'Periodic Verification of Operational Constraints', 'The system shall periodically verify that operational constraints remain valid and aligned with current operating conditions.', 'HIGH','APPROVED', 'Periodic verification ensures constraints remain effective as conditions evolve.', 'ISO 25010 – Safety: Operational Constraint', 'Outdated constraints may fail to prevent hazardous situations.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='RKI'), 'SAF-RKI-01', 'Automated Risk Detection', 'The system shall automatically detect potential safety risks based on predefined rules, thresholds, or patterns.', 'HIGH','APPROVED', 'Automated detection ensures early identification of hazardous conditions.', 'ISO 25010 – Safety: Risk Identification', 'Undetected risks may escalate into safety incidents or system failures.'),
    ((select id from category_sub where short_name='RKI'), 'SAF-RKI-02', 'Real-Time Risk Monitoring', 'The system shall continuously monitor operational data to identify emerging risks in real time.', 'HIGH','APPROVED', 'Real-time monitoring enables timely intervention.', 'ISO 25010 – Safety: Risk Identification', 'Delayed detection increases the likelihood of harm or system damage.'),
    ((select id from category_sub where short_name='RKI'), 'SAF-RKI-03', 'Risk Classification Mechanism', 'The system shall classify identified risks by severity, likelihood, and potential impact.', 'HIGH','APPROVED', 'Classification supports prioritization and appropriate response.', 'ISO 25010 – Safety: Risk Identification', 'Unclassified risks may be mishandled or ignored, increasing danger.'),
    ((select id from category_sub where short_name='RKI'), 'SAF-RKI-04', 'Risk Source Traceability', 'The system shall record the source, trigger, and context of each identified risk.', 'HIGH','APPROVED', 'Traceability supports root-cause analysis and prevention.', 'ISO 25010 – Safety: Risk Identification', 'Lack of traceability prevents effective mitigation and recurrence prevention.'),
    ((select id from category_sub where short_name='RKI'), 'SAF-RKI-05', 'Environmental Risk Identification', 'The system shall identify risks arising from environmental conditions such as temperature, humidity, or vibration.', 'HIGH','APPROVED', 'Environmental awareness prevents unsafe operation in unsuitable conditions.', 'ISO 25010 – Safety: Risk Identification', 'Ignoring environmental risks may lead to equipment failure or hazards.'),
    ((select id from category_sub where short_name='RKI'), 'SAF-RKI-06', 'Human Error Risk Detection', 'The system shall detect potential risks caused by operator mistakes, misuse, or abnormal behavior.', 'HIGH','APPROVED', 'Identifying human error risks improves overall system safety.', 'ISO 25010 – Safety: Risk Identification', 'Unrecognized human errors may lead to accidents or unsafe system states.'),
    ((select id from category_sub where short_name='RKI'), 'SAF-RKI-07', 'Risk Pattern Recognition', 'The system shall identify recurring patterns that indicate emerging or systemic risks.', 'HIGH','APPROVED', 'Pattern recognition helps detect risks before they escalate.', 'ISO 25010 – Safety: Risk Identification', 'Failure to identify patterns may allow repeated unsafe conditions to persist.'),
    ((select id from category_sub where short_name='RKI'), 'SAF-RKI-08', 'Risk Logging and Auditability', 'The system shall log all identified risks with timestamps and relevant diagnostic data.', 'HIGH','APPROVED', 'Logging supports audits, compliance, and continuous safety improvement.', 'ISO 25010 – Safety: Risk Identification', 'Missing logs hinder investigations and regulatory compliance.'),
    ((select id from category_sub where short_name='RKI'), 'SAF-RKI-09', 'Predictive Risk Identification', 'The system shall use predictive indicators or trend analysis to identify risks before they occur.', 'HIGH','APPROVED', 'Predictive identification reduces the likelihood of unexpected failures.', 'ISO 25010 – Safety: Risk Identification', 'Without prediction, risks may only be detected after causing harm.'),
    ((select id from category_sub where short_name='RKI'), 'SAF-RKI-10', 'Risk Identification Coverage Requirements', 'The system shall ensure that all critical functions, components, and interfaces are included in risk identification processes.', 'HIGH','APPROVED', 'Comprehensive coverage prevents blind spots in safety monitoring.', 'ISO 25010 – Safety: Risk Identification', 'Gaps in coverage may leave critical risks undetected.'),
    ((select id from category_sub where short_name='RKI'), 'SAF-RKI-11', 'Operator Notification of Identified Risks', 'The system shall notify operators immediately when a risk is identified, including severity and recommended actions.', 'HIGH','APPROVED', 'Timely notification enables rapid mitigation.', 'ISO 25010 – Safety: Risk Identification', 'Unnotified risks may escalate into hazardous events.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='FSA'), 'SAF-FSA-01', 'Automatic Transition to Fail-Safe State', 'The system shall automatically transition to a predefined fail-safe state when critical failures or anomalies are detected.', 'HIGH','APPROVED', 'Fail-safe transitions prevent hazardous behavior during system faults.', 'ISO 25010 – Safety: Fail Safe', 'Failure to enter a fail-safe state may result in unsafe or uncontrolled system operation.'),
    ((select id from category_sub where short_name='FSA'), 'SAF-FSA-02', 'Fail-Safe State Definition', 'The system shall define and document specific fail-safe states for all critical components and functions.', 'HIGH','APPROVED', 'Clear definitions ensure predictable and safe system behavior during failures.', 'ISO 25010 – Safety: Fail Safe', 'Undefined fail-safe states may lead to inconsistent or unsafe fallback behavior.'),
    ((select id from category_sub where short_name='FSA'), 'SAF-FSA-03', 'Fail-Safe Activation Criteria', 'The system shall specify measurable criteria that trigger fail-safe activation.', 'HIGH','APPROVED', 'Clear criteria ensure timely and consistent fail-safe responses.', 'ISO 25010 – Safety: Fail Safe', 'Ambiguous criteria may delay activation and increase risk of harm.'),
    ((select id from category_sub where short_name='FSA'), 'SAF-FSA-04', 'Fail-Safe Override Restrictions', 'The system shall restrict manual overrides of fail-safe mechanisms to authorized personnel only.', 'HIGH','APPROVED', 'Override restrictions prevent unsafe manual intervention.', 'ISO 25010 – Safety: Fail Safe', 'Unauthorized overrides may disable safety protections and cause accidents.'),
    ((select id from category_sub where short_name='FSA'), 'SAF-FSA-05', 'Fail-Safe Recovery Procedures', 'The system shall provide documented procedures for safely recovering from a fail-safe state.', 'HIGH','APPROVED', 'Recovery procedures ensure safe restoration of normal operation.', 'ISO 25010 – Safety: Fail Safe', 'Improper recovery may reintroduce unsafe conditions or system instability.'),
    ((select id from category_sub where short_name='FSA'), 'SAF-FSA-06', 'Fail-Safe Redundancy', 'The system shall implement redundant mechanisms to ensure fail-safe activation even if primary detection methods fail.', 'HIGH','APPROVED', 'Redundancy increases reliability of safety responses.', 'ISO 25010 – Safety: Fail Safe', 'A single point of failure may prevent fail-safe activation during critical events.'),
    ((select id from category_sub where short_name='FSA'), 'SAF-FSA-07', 'Fail-Safe Event Logging', 'The system shall log all fail-safe activations, including triggers, timestamps, and system state.', 'HIGH','APPROVED', 'Logging supports root-cause analysis and safety audits.', 'ISO 25010 – Safety: Fail Safe', 'Missing logs hinder investigation and may hide recurring safety issues.'),
    ((select id from category_sub where short_name='FSA'), 'SAF-FSA-08', 'Fail-Safe Notification', 'The system shall notify operators immediately when a fail-safe state is activated.', 'HIGH','APPROVED', 'Timely notification enables rapid assessment and corrective action.', 'ISO 25010 – Safety: Fail Safe', 'Unnotified fail-safe events may leave operators unaware of critical issues.'),
    ((select id from category_sub where short_name='FSA'), 'SAF-FSA-09', 'Fail-Safe Testing Capability', 'The system shall support periodic testing of fail-safe mechanisms without disrupting normal operation.', 'HIGH','APPROVED', 'Testing ensures fail-safe mechanisms remain functional over time.', 'ISO 25010 – Safety: Fail Safe', 'Untested fail-safe mechanisms may fail when needed most.'),
    ((select id from category_sub where short_name='FSA'), 'SAF-FSA-10', 'Graceful Degradation to Fail-Safe State', 'The system shall degrade functionality gracefully when transitioning into a fail-safe state.', 'HIGH','APPROVED', 'Graceful degradation prevents abrupt shutdowns that may cause harm.', 'ISO 25010 – Safety: Fail Safe', 'Abrupt transitions may cause unsafe or unpredictable system behavior.'),
    ((select id from category_sub where short_name='FSA'), 'SAF-FSA-11', 'Fail-Safe State Integrity Protection', 'The system shall ensure that fail-safe states cannot be altered, bypassed, or corrupted by faults or unauthorized actions.', 'HIGH','APPROVED', 'Integrity protection ensures reliability of safety-critical fallback states.', 'ISO 25010 – Safety: Fail Safe', 'Compromised fail-safe states may fail to protect users during emergencies.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='HWA'), 'SAF-HWA-01', 'Hazard Detection Alerts', 'The system shall generate immediate alerts when a hazardous condition is detected.', 'HIGH','APPROVED', 'Immediate alerts allow operators to take corrective action quickly.', 'ISO 25010 – Safety: Hazard Warning', 'Delayed or missing alerts may result in accidents or system damage.'),
    ((select id from category_sub where short_name='HWA'), 'SAF-HWA-02', 'Multi-Level Hazard Severity Warnings', 'The system shall classify and display hazard warnings according to severity levels (e.g., caution, warning, critical).', 'HIGH','APPROVED', 'Severity levels help prioritize operator response.', 'ISO 25010 – Safety: Hazard Warning', 'Unclassified warnings may cause confusion and improper response.'),
    ((select id from category_sub where short_name='HWA'), 'SAF-HWA-03', 'Clear and Unambiguous Warning Messages', 'The system shall present hazard warnings using clear, concise, and unambiguous language.', 'HIGH','APPROVED', 'Clear warnings reduce misinterpretation and improve safety.', 'ISO 25010 – Safety: Hazard Warning', 'Ambiguous warnings may lead to incorrect or delayed operator actions.'),
    ((select id from category_sub where short_name='HWA'), 'SAF-HWA-04', 'Visual and Audible Hazard Indicators', 'The system shall provide both visual and audible indicators for critical hazards.', 'HIGH','APPROVED', 'Multi-modal warnings ensure hazards are noticed promptly.', 'ISO 25010 – Safety: Hazard Warning', 'Single-mode warnings may be missed, especially in noisy or visually busy environments.'),
    ((select id from category_sub where short_name='HWA'), 'SAF-HWA-05', 'Persistent Hazard Notification', 'The system shall maintain hazard warnings until the hazardous condition is resolved or acknowledged by an authorized operator.', 'HIGH','APPROVED', 'Persistent warnings ensure hazards are not overlooked.', 'ISO 25010 – Safety: Hazard Warning', 'Warnings that disappear prematurely may leave hazards unaddressed.'),
    ((select id from category_sub where short_name='HWA'), 'SAF-HWA-06', 'Hazard Warning Prioritization', 'The system shall prioritize hazard warnings so that critical hazards override non-critical notifications.', 'HIGH','APPROVED', 'Prioritization ensures the most dangerous conditions receive immediate attention.', 'ISO 25010 – Safety: Hazard Warning', 'Low-priority warnings may obscure critical hazards, delaying response.'),
    ((select id from category_sub where short_name='HWA'), 'SAF-HWA-07', 'Hazard Warning Logging', 'The system shall log all hazard warnings, including timestamps, severity, and triggering conditions.', 'HIGH','APPROVED', 'Logging supports safety audits and root-cause analysis.', 'ISO 25010 – Safety: Hazard Warning', 'Missing logs hinder investigations and reduce accountability.'),
    ((select id from category_sub where short_name='HWA'), 'SAF-HWA-08', 'Operator Guidance for Hazard Response', 'The system shall provide recommended actions or guidance when a hazard warning is issued.', 'HIGH','APPROVED', 'Guidance helps operators respond quickly and correctly.', 'ISO 25010 – Safety: Hazard Warning', 'Without guidance, operators may take ineffective or unsafe actions.'),
    ((select id from category_sub where short_name='HWA'), 'SAF-HWA-09', 'Redundancy in Hazard Warning Systems', 'The system shall implement redundant mechanisms to ensure hazard warnings are delivered even if one subsystem fails.', 'HIGH','APPROVED', 'Redundancy increases reliability of safety-critical warnings.', 'ISO 25010 – Safety: Hazard Warning', 'A single point of failure may prevent critical hazards from being communicated.'),
    ((select id from category_sub where short_name='HWA'), 'SAF-HWA-10', 'Context-Aware Hazard Warnings', 'The system shall tailor hazard warnings based on operational context, such as mode, environment, or user role.', 'HIGH','APPROVED', 'Context-aware warnings improve relevance and reduce alarm fatigue.', 'ISO 25010 – Safety: Hazard Warning', 'Generic warnings may be ignored or misunderstood, increasing risk.'),
    ((select id from category_sub where short_name='HWA'), 'SAF-HWA-11', 'Pre-Hazard Early Warning Indicators', 'The system shall provide early warning indicators when conditions are trending toward a hazardous state.', 'HIGH','APPROVED', 'Early warnings allow proactive intervention before hazards occur.', 'ISO 25010 – Safety: Hazard Warning', 'Without early indicators, hazards may only be detected after becoming critical.');
INSERT INTO requirements
	(category_sub_id, identifier, title, description, priority, status, rationale, source, risk_if_violated)
VALUES
    ((select id from category_sub where short_name='SIN'), 'SAF-SIN-01', 'Safe Interface Compatibility', 'The system shall verify compatibility with external systems and components before integration to prevent unsafe interactions.', 'HIGH','APPROVED', 'Compatibility checks prevent hazardous behavior caused by mismatched interfaces.', 'ISO 25010 – Safety: Safe Integration', 'Incompatible integrations may lead to unpredictable or unsafe system responses.'),
    ((select id from category_sub where short_name='SIN'), 'SAF-SIN-02', 'Controlled Integration Points', 'The system shall restrict integration to approved and validated interfaces only.', 'HIGH','APPROVED', 'Controlled integration reduces the risk of unsafe or unauthorized system interactions.', 'ISO 25010 – Safety: Safe Integration', 'Uncontrolled integration points may introduce vulnerabilities or hazardous conditions.'),
    ((select id from category_sub where short_name='SIN'), 'SAF-SIN-03', 'Integration Failure Detection', 'The system shall detect failures in integrated components or systems and respond safely.', 'HIGH','APPROVED', 'Detecting integration failures prevents cascading hazards.', 'ISO 25010 – Safety: Safe Integration', 'Undetected failures may propagate and compromise overall system safety.'),
    ((select id from category_sub where short_name='SIN'), 'SAF-SIN-04', 'Safe Integration Protocols', 'The system shall use validated communication and integration protocols designed to prevent unsafe data exchange.', 'HIGH','APPROVED', 'Safe protocols ensure reliable and predictable interactions.', 'ISO 25010 – Safety: Safe Integration', 'Unsafe protocols may transmit corrupted or hazardous commands.'),
    ((select id from category_sub where short_name='SIN'), 'SAF-SIN-05', 'Isolation of Unsafe Components', 'The system shall isolate components that exhibit unsafe behavior to prevent them from affecting other integrated systems.', 'HIGH','APPROVED', 'Isolation limits the spread of hazardous conditions.', 'ISO 25010 – Safety: Safe Integration', 'Failure to isolate unsafe components may compromise the entire system.'),
    ((select id from category_sub where short_name='SIN'), 'SAF-SIN-06', 'Integration Validation Testing', 'The system shall perform validation testing after integrating new or updated components to ensure safe operation.', 'HIGH','APPROVED', 'Validation testing confirms that integration has not introduced hazards.', 'ISO 25010 – Safety: Safe Integration', 'Unvalidated integrations may introduce hidden safety risks.'),
    ((select id from category_sub where short_name='SIN'), 'SAF-SIN-07', 'Safe Data Exchange Requirements', 'The system shall validate all incoming and outgoing data exchanged with integrated systems to ensure it meets safety constraints.', 'HIGH','APPROVED', 'Data validation prevents unsafe commands or corrupted information from propagating.', 'ISO 25010 – Safety: Safe Integration', 'Invalid or unsafe data may trigger hazardous system behavior.'),
    ((select id from category_sub where short_name='SIN'), 'SAF-SIN-08', 'Integration Error Logging', 'The system shall log all integration-related errors, anomalies, and unsafe interactions.', 'HIGH','APPROVED', 'Logging supports root-cause analysis and continuous safety improvement.', 'ISO 25010 – Safety: Safe Integration', 'Missing logs hinder investigations and may allow recurring unsafe conditions.'),
    ((select id from category_sub where short_name='SIN'), 'SAF-SIN-09', 'Safe Integration Rollback Mechanism', 'The system shall support rollback to a safe state if integration with an external component fails.', 'HIGH','APPROVED', 'Rollback prevents unsafe operation after failed integrations.', 'ISO 25010 – Safety: Safe Integration', 'Without rollback, the system may remain in an unstable or hazardous state.'),
    ((select id from category_sub where short_name='SIN'), 'SAF-SIN-10', 'Integration Dependency Verification', 'The system shall verify that all required dependencies for integrated components are present and functioning safely.', 'HIGH','APPROVED', 'Dependency checks prevent unsafe operation due to missing or faulty components.', 'ISO 25010 – Safety: Safe Integration', 'Missing dependencies may cause unpredictable or hazardous behavior.'),
    ((select id from category_sub where short_name='SIN'), 'SAF-SIN-11', 'Safe Shutdown on Integration Failure', 'The system shall perform a controlled shutdown if integration failures compromise safe operation.', 'HIGH','APPROVED', 'Controlled shutdown prevents escalation of unsafe conditions.', 'ISO 25010 – Safety: Safe Integration', 'Uncontrolled operation after integration failure may lead to severe hazards.');