CREATE TABLE NFR.requirements (
    nfr_id              BINARY(16) NOT NULL DEFAULT (UUID_TO_BIN(UUID())),
    category_sub_id     BINARY(16) NOT NULL,
    identifier          VARCHAR(40) UNIQUE NOT NULL,           -- e.g. NFR-SEC-017, PERF-2025-003
    title               VARCHAR(250) UNIQUE NOT NULL,
    description         TEXT NOT NULL,                          -- normative statement
    priority            VARCHAR(60) NOT NULL,
    status              VARCHAR(60) NOT NULL,

    -- Quantitative / measurable targets (very important for NFRs)
    target_value        VARCHAR(120),                           -- "≤ 250 ms", "≥ 99.95%", "AES-256", "≤ 5 defects/kloc"
    threshold_value     VARCHAR(120),                           -- warning / soft limit
    unit                VARCHAR(60),                            -- "ms", "%", "concurrent users", "GB/month"
    measurement_method  VARCHAR(200),                           -- "average over 95th percentile", "SonarQube", "pen-test report"

    rationale           TEXT NOT NULL,                          -- business / risk / regulation reason
    source              VARCHAR(200) NOT NULL,                  -- "Stakeholder X", "GDPR Art. 32", "Competitor benchmark"
    risk_if_violated    TEXT NOT NULL,

    created_at          DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at          DATETIME ON UPDATE CURRENT_TIMESTAMP,

    PRIMARY KEY (`nfr_id`),
    CONSTRAINT fk_nfr_category_sub  FOREIGN KEY (category_sub_id)  REFERENCES category_sub(id)
);

